(function(){var m=window.SITE_DATA_BY_DOMAIN=window.SITE_DATA_BY_DOMAIN||{};var d=m["moe"]=m["moe"]||{};d["algorithms"]=[{"id":"alg-capacity-factor-routing","name":"容量因子路由与令牌丢弃","year":2021,"direction":"dir-moe-routing-capacity","tier":"classic","problem":"MoE 推理中专家负载随批次波动，无容量约束时热点专家溢出导致 All-to-All 缓冲膨胀与长尾时延；需要在不改变模型的前提下把每专家 token 数压到可预测上界。","idea":"为每个专家设定容量上限 capacity = ceil(capacity_factor × tokens/batch / num_experts)，超出容量的 token 被丢弃或走残差旁路，使 All-to-All 的发送缓冲与 GEMM 形状在编译期即可静态确定。","how":"解决的具体问题：MoE 推理中专家负载随批次波动，无容量约束时热点专家溢出，导致 All-to-All 发送缓冲膨胀与长尾时延；需要在不改模型的前提下把每专家 token 数压到可预测上界。 机制步骤：请求进调度器后切成固定 token 预算的 micro-batch，路由器对每 token 算 top-k 专家打分；按打分排序后为每专家截断到 capacity，溢出 token 标记 dropped 并直接走残差连接。 机制步骤续：据 capacity 生成静态 dispatch 矩阵（token 到专家槽位），All-to-All 发送缓冲大小在 kernel launch 前确定；专家侧按固定 M=capacity 的分组 GEMM 计算，tcgen05 tile 形状无需运行时重排；combine 按原路由权重加权回填，dropped token 用残差输出进入下一层。","flow":["请求进入调度器后被切成固定 token 预算的 micro-batch，路由器对每个 token 计算 top-k 专家打分","按打分排序后为每个专家截断到 capacity，溢出 token 标记为 dropped 并直接走残差连接","根据 capacity 生成静态的 dispatch 矩阵（token→专家槽位），All-to-All 发送缓冲大小在 kernel launch 前确定","专家侧按固定 M=capacity 的分组 GEMM 计算，tcgen05 的 tile 形状无需运行时重排","combine 阶段按原路由权重加权回填，dropped token 使用残差输出，进入下一层"],"formula":"$$\\text{capacity}=\\left\\lceil \\frac{C \\cdot T}{E} \\right\\rceil,\\quad \\text{drop rate}=\\frac{1}{T}\\sum_{t=1}^{T}\\mathbb{1}\\left[\\text{rank}_e(t)>\\text{capacity}\\right]$$","pros":["All-to-All 缓冲与分组 GEMM 形状静态化，避免运行时动态分配与 kernel 重编译，decode 阶段 P99 时延可预测","容量因子是单一可调旋钮，可在 SLO 与质量之间做显式权衡（如 C=1.25 时 drop rate 通常 <1%）"],"cons":["丢弃 token 直接损失模型质量，长尾请求（如代码、数学）在专家偏斜时 drop rate 显著升高","容量因子需按负载分布离线标定，流量分布漂移后要么浪费显存要么丢 token 增多"],"papers":["paper-switch-transformers-scaling-to-trill-2021","paper-gshard-scaling-giant-models-with-con-2020"],"successors":["alg-chunked-prefill"],"facts":["解决的具体问题：MoE 推理中专家负载随批次波动，无容量约束时热点专家溢出，导致 All-to-All 发送缓冲膨胀与长尾时延；需要在不改模型的前提下把每专家 token 数压到可预测上界。","机制步骤：请求进调度器后切成固定 token 预算的 micro-batch，路由器对每 token 算 top-k 专家打分；按打分排序后为每专家截断到 capacity，溢出 token 标记 dropped 并直接走残差连接。","机制步骤续：据 capacity 生成静态 dispatch 矩阵（token 到专家槽位），All-to-All 发送缓冲大小在 kernel launch 前确定；专家侧按固定 M=capacity 的分组 GEMM 计算，tcgen05 tile 形状无需运行时重排；combine 按原路由权重加权回填，dropped token 用残差输出进入下一层。","核心公式：$$\\text{capacity}=\\left\\lceil \\text{capacity\\_factor}\\times\\frac{\\text{tokens per batch}}{\\text{num\\_experts}}\\right\\rceil$$，其中 capacity_factor 为单一可调旋钮，tokens per batch 为 micro-batch 内 token 数，num_experts 为专家数，capacity 即每专家可接收的 token 上界。","负载配方：请求按固定 token 预算切 micro-batch，批大小受 capacity 与显存约束；SLO 以 decode 阶段 P99 时延为目标，容量因子按负载分布离线标定，材料给出 C=1.25 时 drop rate 通常 <1%。","部署配方：硬件档位与并行拓扑材料未给出具体型号；量化与 KV cache 策略材料未给出；关键工程约束是 All-to-All 缓冲与分组 GEMM 形状在编译期静态确定，tcgen05 tile 形状无需运行时重排。","稳定性技巧与失败模式：容量因子需按负载分布离线标定，流量分布漂移后要么浪费显存要么丢 token 增多；长尾请求（代码、数学）在专家偏斜时 drop rate 显著升高，直接损失模型质量。","与相邻算法差别：专家选择路由反转方向使每专家负载恒等于 k、彻底无丢弃但破坏因果性；无丢弃块稀疏分组 GEMM 用块级 padding 替代 token 丢弃；本算法以丢弃换静态形状与可预测 P99。","适用边界与规模上限：优点是 All-to-All 缓冲与分组 GEMM 形状静态化，避免运行时动态分配与 kernel 重编译，decode P99 可预测；代价是丢弃 token 损失质量，容量因子需离线标定，规模上限受负载分布稳定性约束，材料未给出具体专家数上限。"],"anchors":["C=1.25","drop rate <1%"],"pitfalls":["流量分布漂移后容量因子失配：偏小则 drop rate 升高、长尾请求质量骤降，偏大则 All-to-All 缓冲与显存浪费。","代码、数学等长尾请求在专家偏斜时 drop rate 显著高于均值，dropped token 走残差旁路导致这些请求的输出质量不可控。","容量因子按离线负载标定，在线 batch 组成变化后静态 dispatch 矩阵与 GEMM 形状虽可预测，但专家利用率下降、吞吐不达预期。"]},{"id":"alg-expert-choice-routing","name":"专家选择路由","year":2022,"direction":"dir-expert-parallel-alltoall","tier":"recent","problem":"token 选择专家的 top-k 路由天然造成负载不均，容量因子只能靠丢弃来兜底；需要一种从机制上保证每专家负载严格相等的路由方式，消除丢弃。","idea":"反转路由方向：每个专家按打分挑选固定数量 k 的 token，使每专家负载恒等于 k，天然无丢弃、无溢出，代价是 token 可能被 0 个或多个专家选中。","how":"解决的问题：token-choice 路由下专家负载由数据分布决定，容量因子只能事后截断，无法保证每个专家恰好处理固定数量令牌，导致分组 GEMM 的 tile 形状抖动。 机制步骤一：计算 token 与所有专家的亲和度矩阵 $S$（$T \\times E$），每个专家沿 token 维取 top-c，得到 $E \\times c$ 的选择掩码。 机制步骤二：被多个专家选中的 token 按权重归一化后合并，按专家维度重排 token，形成 $E$ 个固定大小 $c$ 的连续块。","flow":["路由器计算 token×专家 的打分矩阵 G（形状 T×E）","对每个专家列做 top-k 选择，得到该专家负责的 token 集合，每专家恰好 k 个","构建转置的 dispatch 矩阵（专家→token），All-to-All 发送量严格为 E×k","分组 GEMM 以固定 M=k 执行，combine 时对每个 token 按其被选中的专家数做加权平均","未被任何专家选中的 token 走残差旁路，被多个专家选中的 token 权重归一化"],"formula":"$$\\mathbf{I}=\\text{TopK}_{\\text{col}}\\left(\\mathbf{G}\\right)\\in\\{0,1\\}^{T\\times E},\\quad \\sum_{t}\\mathbf{I}_{t,e}=k\\ \\ \\forall e,\\quad \\mathbf{y}_t=\\frac{\\sum_e \\mathbf{I}_{t,e}\\,g_{t,e}\\,\\text{Expert}_e(\\mathbf{x}_t)}{\\sum_e \\mathbf{I}_{t,e}g_{t,e}}$$","pros":["每专家负载严格等于 k，All-to-All 流量与 GEMM 形状完全确定，彻底消除容量因子与 token 丢弃","负载均衡由路由机制保证而非事后截断，专家利用率接近 100%"],"cons":["因果性被破坏：token 能否被专家处理取决于同批次其他 token，自回归 decode 时需按 batch 整体路由，与逐 token 生成不兼容","部分 token 被 0 个专家选中（欠拟合）或被多个专家选中（计算量翻倍），实际 FLOPs 高于 top-k 名义值"],"papers":["paper-mixture-of-experts-with-expert-choic-2022"],"successors":["alg-nvfp4-moe-weights"],"facts":["解决的问题：token-choice 路由下专家负载由数据分布决定，容量因子只能事后截断，无法保证每个专家恰好处理固定数量令牌，导致分组 GEMM 的 tile 形状抖动。","机制步骤一：计算 token 与所有专家的亲和度矩阵 $S$（$T \\times E$），每个专家沿 token 维取 top-c，得到 $E \\times c$ 的选择掩码。","机制步骤二：被多个专家选中的 token 按权重归一化后合并，按专家维度重排 token，形成 $E$ 个固定大小 $c$ 的连续块。","机制步骤三：分组 GEMM 以固定 tile 执行，结果按 token 索引散射回序列。","核心公式：专家 $e$ 的选择为 $$\\mathcal{T}_e = \\text{top-}c\\left(\\{S_{t,e}\\}_{t=1}^{T}\\right)$$，其中 $S_{t,e}$ 为 token $t$ 与专家 $e$ 的亲和度、$c$ 为每专家容量；每个专家负载严格等于 $c$。","负载配方：每个专家处理 token 数严格等于 $c$，分组 GEMM tile 形状固定；材料未给出具体请求形态、批大小与 SLO 数值。","部署配方：分组 GEMM 以固定 tile 执行，tcgen05 流水线无气泡；量化与 KV cache 细节材料未给出。","稳定性技巧与失败模式：自回归解码时 batch 内 token 数远小于 $c$，专家选择退化为近似全选，失去稀疏性；部分 token 可能不被任何专家选中，需要额外兜底路由。","与相邻算法差别：相比容量因子路由，本方法反转选择方向，负载均衡由算法保证而非统计保证，无需容量因子与令牌丢弃。","适用边界：适合预填阶段 token 数远大于 $c$ 的场景；解码阶段 batch 小、稀疏性退化，规模上限受 $c$ 与 batch 大小关系约束。"],"anchors":["paper-mixture-of-experts-with-expert-choic-2022"],"pitfalls":["自回归解码 batch 内 token 数远小于 c 时退化为近似全选，失去稀疏性。","部分 token 不被任何专家选中，缺乏兜底路由时输出缺失。","固定 tile 形状在专家数变化时需重新调优，否则 tcgen05 流水线出现气泡。"]},{"id":"alg-megablocks-dropless","name":"无丢弃块稀疏分组 GEMM","year":2022,"direction":"dir-grouped-gemm-tcgen05","tier":"recent","problem":"容量因子路由靠丢弃保形状，专家选择路由破坏因果性；需要一种既不丢 token 又能把不规则专家负载映射到高效 GEMM 的工程方案，避免 padding 浪费。","idea":"用块稀疏（block-sparse）矩阵乘替代固定容量的分组 GEMM：把 token×专家 的稀疏路由矩阵按固定 block 切分，只对非零块做 GEMM，负载不均时通过块级 padding 而非 token 丢弃来对齐。","how":"解决的具体问题：容量因子路由靠丢弃保形状，专家选择路由破坏因果性；需要既不丢 token 又能把不规则专家负载映射到高效 GEMM 的工程方案，避免 padding 浪费。 机制步骤：路由器产出 token 到专家的稀疏指派，按 block（如 128 token × 1 专家）聚合为块稀疏结构；统计每块非零 token 数，生成块级 offset 与块内 token 索引。 机制步骤续：All-to-All 按块发送，接收端把同专家块拼接为连续段，不足一个 block 的用零填充；对每个非零块调用分组 GEMM，块内 M 维按实际 token 数截断，N/K 维用 tcgen05 的 MMA tile；combine 按块内索引散射回原 token 位置，padding 位置不参与加权。","flow":["路由器产出 token→专家的稀疏指派，按 block（如 128 token × 1 专家）聚合为块稀疏结构","统计每个块的非零 token 数，生成块级 offset 与块内 token 索引","All-to-All 按块发送，接收端把同专家块拼接为连续段，不足一个 block 的用零填充","对每个非零块调用分组 GEMM，块内 M 维按实际 token 数截断，N/K 维用 tcgen05 的 MMA tile","combine 阶段按块内索引散射回原 token 位置，padding 位置不参与加权"],"formula":"$$\\text{FLOPs}_{\\text{eff}}=\\sum_{b\\in\\text{blocks}}\\mathbb{1}[\\text{nnz}_b>0]\\cdot 2\\,M_b\\,N\\,K,\\quad \\text{waste}=\\frac{\\sum_b(\\text{pad}_b)}{\\sum_b M_b}$$","pros":["无 token 丢弃，质量与稠密模型对齐；块级 padding 浪费通常 <10%，远低于按最大专家负载统一 padding 的浪费","块稀疏结构可映射到 tcgen05 的 MMA 指令，分组 GEMM 吞吐接近稠密 GEMM 的 80% 以上"],"cons":["块大小是硬约束：block 越小浪费越少但 kernel launch 与索引开销越大，block 越大则小专家浪费显著","实现复杂度高，需要自定义块稀疏 dispatch/combine kernel，跨框架移植性差"],"papers":["paper-megablocks-efficient-sparse-training-2022","paper-tutel-adaptive-mixture-of-experts-at-2022"],"successors":["alg-moe-kv-compress"],"facts":["解决的具体问题：容量因子路由靠丢弃保形状，专家选择路由破坏因果性；需要既不丢 token 又能把不规则专家负载映射到高效 GEMM 的工程方案，避免 padding 浪费。","机制步骤：路由器产出 token 到专家的稀疏指派，按 block（如 128 token × 1 专家）聚合为块稀疏结构；统计每块非零 token 数，生成块级 offset 与块内 token 索引。","机制步骤续：All-to-All 按块发送，接收端把同专家块拼接为连续段，不足一个 block 的用零填充；对每个非零块调用分组 GEMM，块内 M 维按实际 token 数截断，N/K 维用 tcgen05 的 MMA tile；combine 按块内索引散射回原 token 位置，padding 位置不参与加权。","核心公式：$$\\text{waste}=\\frac{\\sum_{b}\\left(\\text{block\\_size}-n_b\\right)}{\\sum_{b} n_b}$$，其中 $$n_b$$ 为第 b 个非零块的实际 token 数，block_size 为块容量；块级 padding 浪费通常 <10%，远低于按最大专家负载统一 padding 的浪费。","负载配方：请求按 block 聚合路由，批大小决定块数量与非零块比例；SLO 关注分组 GEMM 吞吐与尾时延，材料未给出具体批大小与 SLO 数值。","部署配方：硬件档位与并行拓扑材料未给出具体型号；量化与 KV cache 策略材料未给出；关键工程特征是块稀疏结构可映射到 tcgen05 的 MMA 指令，分组 GEMM 吞吐接近稠密 GEMM 的 80% 以上。","稳定性技巧与失败模式：块大小是硬约束，block 越小浪费越少但 kernel launch 与索引开销越大，block 越大则小专家浪费显著；实现复杂度高，需自定义块稀疏 dispatch/combine kernel，跨框架移植性差。","与相邻算法差别：容量因子路由以 token 丢弃保形状，专家选择路由破坏因果性；本算法用块级 padding 而非 token 丢弃来对齐，质量与稠密模型对齐，无 token 丢弃。","适用边界与规模上限：无 token 丢弃使质量与稠密模型对齐，块级 padding 浪费通常 <10%；适用边界受 block 大小与专家负载分布约束，规模上限受自定义 kernel 实现复杂度与跨框架移植性限制，材料未给出具体专家数上限。"],"anchors":["128 token × 1 专家","padding 浪费 <10%","分组 GEMM 吞吐接近稠密 GEMM 的 80% 以上"],"pitfalls":["块大小选择失当：block 过小则 kernel launch 与索引开销压过收益，block 过大则小专家块内 padding 浪费显著。","需自定义块稀疏 dispatch/combine kernel，跨框架移植性差，换框架后需重写并重新验证正确性。","专家负载高度偏斜时非零块数量与块内截断频繁变化，块级 offset 与索引生成开销上升，吞吐低于预期。"]},{"id":"alg-nvfp4-moe-quant","name":"NVFP4 权重激活微缩放量化","year":2023,"direction":"dir-nvfp4-fp8-quant","tier":"recent","problem":"MoE 推理是显存带宽受限的，专家权重占显存主体；FP8 已把权重压到 1 字节，但 decode 阶段每 token 仍需读取全部激活专家的权重，需要 4-bit 权重与激活进一步降带宽。","idea":"采用 NVFP4（E2M1 + 每 16 元素共享 FP8 scale）的微缩放格式，权重与激活都量化到 4-bit，分组 GEMM 在 tcgen05 上以 FP4 MMA 执行，scale 在累加前反量化。","how":"解决的具体问题：MoE 推理是显存带宽受限的，专家权重占显存主体；FP8 已把权重压到 1 字节，但 decode 阶段每 token 仍需读取全部激活专家的权重，需要 4-bit 权重与激活进一步降带宽。 机制步骤：离线校准对每个专家的权重按 16 元素块计算 FP8 scale，权重舍入到 E2M1；运行时激活按 token 分组量化到 NVFP4，scale 随 token 一起进入 dispatch 缓冲。 机制步骤续：All-to-All 传输 4-bit 权重索引与激活，带宽相比 FP8 减半；tcgen05 FP4 MMA 执行分组 GEMM，累加器为 FP32，块内按 scale 反量化；combine 后激活反量化回 BF16 进入下一层，KV cache 仍保持 FP8/BF16。","flow":["离线校准：对每个专家的权重按 16 元素块计算 FP8 scale，权重舍入到 E2M1","运行时激活按 token 分组量化到 NVFP4，scale 随 token 一起进入 dispatch 缓冲","All-to-All 传输 4-bit 权重索引与激活，带宽相比 FP8 减半","tcgen05 FP4 MMA 执行分组 GEMM，累加器为 FP32，块内按 scale 反量化","combine 后激活反量化回 BF16 进入下一层，KV cache 仍保持 FP8/BF16"],"formula":"$$w_{i}=\\text{FP4}\\left(\\frac{w_i}{s_b}\\right),\\quad s_b=\\frac{\\max_{j\\in b}|w_j|}{\\text{FP8}_{\\max}},\\quad \\hat{y}=\\sum_b s_b^{w}s_b^{x}\\sum_{i\\in b}\\hat{w}_i\\hat{x}_i$$","pros":["权重与激活带宽相比 FP8 减半，decode 阶段专家权重读取时间近似减半，直接抬升 tokens/s","tcgen05 原生支持 FP4 MMA，分组 GEMM 吞吐可达 FP8 的 2 倍，且微缩放精度损失在 MoE 上通常 <1% 困惑度"],"cons":["4-bit 激活量化对 outlier 敏感，需 per-token 或 per-block scale，校准不当会导致路由打分漂移、专家选择错误","反量化 scale 引入额外 kernel 与寄存器压力，小 batch decode 时 scale 开销占比不可忽略"],"papers":["paper-microscaling-data-formats-for-deep-l-2023","paper-fp8-formats-for-deep-learning-2022"],"successors":["alg-chunked-prefill-piggyback"],"facts":["解决的具体问题：MoE 推理是显存带宽受限的，专家权重占显存主体；FP8 已把权重压到 1 字节，但 decode 阶段每 token 仍需读取全部激活专家的权重，需要 4-bit 权重与激活进一步降带宽。","机制步骤：离线校准对每个专家的权重按 16 元素块计算 FP8 scale，权重舍入到 E2M1；运行时激活按 token 分组量化到 NVFP4，scale 随 token 一起进入 dispatch 缓冲。","机制步骤续：All-to-All 传输 4-bit 权重索引与激活，带宽相比 FP8 减半；tcgen05 FP4 MMA 执行分组 GEMM，累加器为 FP32，块内按 scale 反量化；combine 后激活反量化回 BF16 进入下一层，KV cache 仍保持 FP8/BF16。","核心公式：$$x_{q}=\\operatorname{round}_{\\text{E2M1}}\\left(\\frac{x}{s}\\right),\\quad s=\\frac{\\max_{16}|x|}{\\text{FP8\\_max}}$$，其中 x 为 16 元素块内原始值，s 为该块共享的 FP8 scale，$$x_q$$ 为 E2M1 量化值；反量化在累加前按块内 scale 执行。","负载配方：decode 阶段每 token 需读取全部激活专家权重，批大小受显存带宽约束；SLO 关注 tokens/s 与尾时延，材料未给出具体批大小与 SLO 数值。","部署配方：硬件档位需支持 tcgen05 FP4 MMA；并行拓扑材料未给出具体型号；权重与激活均量化为 NVFP4（E2M1 + 每 16 元素共享 FP8 scale），KV cache 保持 FP8/BF16。","稳定性技巧与失败模式：4-bit 激活量化对 outlier 敏感，需 per-token 或 per-block scale，校准不当会导致路由打分漂移、专家选择错误；反量化 scale 引入额外 kernel 与寄存器压力，小 batch decode 时 scale 开销占比不可忽略。","与相邻算法差别：FP8 把权重压到 1 字节，本算法用 NVFP4 微缩放把权重与激活都压到 4-bit，分组 GEMM 在 tcgen05 上以 FP4 MMA 执行；与容量因子、专家选择等路由算法正交，属量化维度。","适用边界与规模上限：权重与激活带宽相比 FP8 减半，decode 阶段专家权重读取时间近似减半，直接抬升 tokens/s；tcgen05 原生支持 FP4 MMA，分组 GEMM 吞吐可达 FP8 的 2 倍，微缩放精度损失在 MoE 上通常 <1% 困惑度；规模上限受 outlier 敏感性与 scale 开销约束，材料未给出具体专家数上限。"],"anchors":["每 16 元素共享 FP8 scale","E2M1","吞吐可达 FP8 的 2 倍","困惑度损失 <1%"],"pitfalls":["4-bit 激活量化对 outlier 敏感，per-token 或 per-block scale 校准不当会导致路由打分漂移、专家选择错误。","反量化 scale 引入额外 kernel 与寄存器压力，小 batch decode 时 scale 开销占比不可忽略，吞吐收益被抵消。","权重离线校准与运行时激活分布不一致时，NVFP4 量化误差累积到 combine 后激活，逐层放大影响输出质量。"]},{"id":"alg-paged-kv-moe","name":"分页 KV 与专家权重共存显存","year":2023,"direction":"dir-kv-cache-compression","tier":"recent","problem":"MoE 服务中专家权重常驻显存占用巨大，KV cache 随并发线性增长，二者争抢同一块 HBM；连续分配的 KV 造成碎片，长上下文请求无法与高并发共存。","idea":"把 KV cache 切为固定大小的 page 并按需分配，专家权重按热度分层驻留（热专家常驻 HBM、冷专家放 CPU/ NVMe），用统一的显存池管理权重与 KV page，按 SLO 动态调整二者配额。","how":"解决的具体问题是 MoE 服务中专家权重常驻 HBM 与随并发线性增长的 KV cache 争抢同一块 HBM，且连续分配的 KV 造成外部碎片，使长上下文请求无法与高并发请求共存。 机制按数据流顺序为：请求进入时按最大生成长度预留 KV page 数，page 从统一显存池分配且不要求物理连续；attention kernel 按 page table gather KV，FlashAttention 以 page 为粒度做 IO；专家权重按访问频次统计热度，热专家常驻 HBM、冷专家换出到 host 内存并按需预取。 核心配额关系可写为 $$M_{\\text{HBM}} \\ge \\sum_{e \\in \\mathcal{H}} W_e + N_{\\text{page}} \\cdot S_{\\text{page}}$$，其中 $\\mathcal{H}$ 为常驻热专家集合、$W_e$ 为单专家权重字节、$N_{\\text{page}}$ 为已分配 KV page 数、$S_{\\text{page}}$ 为单 page 字节；池水位超过阈值时优先换出 KV page 或降级专家权重以保延迟 SLO。","flow":["请求进入时按最大生成长度预留 KV page 数，page 从统一显存池分配，不要求物理连续","attention kernel 按 page table  gather KV，FlashAttention 以 page 为粒度做 IO","专家权重按访问频次统计热度，热专家常驻 HBM，冷专家换出到 host 内存并在需要时预取","显存池水位超过阈值时触发 KV page 换出或专家权重降级，优先保 KV 以满足延迟 SLO","请求结束后 KV page 归还池，专家权重热度表异步更新"],"formula":"$$\\text{HBM}_{\\text{used}}=\\underbrace{N_{\\text{page}}\\cdot 2\\,L\\,H\\,d}_{\\text{KV}}+\\underbrace{\\sum_{e\\in\\text{hot}}|W_e|}_{\\text{resident experts}},\\quad \\text{hit rate}=\\frac{\\sum_e \\mathbb{1}[e\\in\\text{hot}]\\,n_e}{\\sum_e n_e}$$","pros":["KV 按 page 分配消除外部碎片，长上下文与高并发可在同一显存池内共存，显存利用率提升 20–40%","专家权重分层驻留把冷专家移出 HBM，为 KV 腾出空间，decode 阶段热专家命中率通常 >90%"],"cons":["冷专家换入换出引入 host-device 拷贝，若路由突然偏向冷专家会造成单 token 时延尖峰","page table 间接寻址使 attention kernel 的地址计算更复杂，小 page 时 IO 效率下降"],"papers":["paper-efficient-memory-management-for-larg-2023","paper-floe-on-the-fly-moe-inference-on-mem-2025"],"successors":["alg-pd-disaggregation-moe"],"facts":["解决的具体问题是 MoE 服务中专家权重常驻 HBM 与随并发线性增长的 KV cache 争抢同一块 HBM，且连续分配的 KV 造成外部碎片，使长上下文请求无法与高并发请求共存。","机制按数据流顺序为：请求进入时按最大生成长度预留 KV page 数，page 从统一显存池分配且不要求物理连续；attention kernel 按 page table gather KV，FlashAttention 以 page 为粒度做 IO；专家权重按访问频次统计热度，热专家常驻 HBM、冷专家换出到 host 内存并按需预取。","核心配额关系可写为 $$M_{\\text{HBM}} \\ge \\sum_{e \\in \\mathcal{H}} W_e + N_{\\text{page}} \\cdot S_{\\text{page}}$$，其中 $\\mathcal{H}$ 为常驻热专家集合、$W_e$ 为单专家权重字节、$N_{\\text{page}}$ 为已分配 KV page 数、$S_{\\text{page}}$ 为单 page 字节；池水位超过阈值时优先换出 KV page 或降级专家权重以保延迟 SLO。","负载配方：请求形态为长上下文与高并发混合的在线服务，批大小随并发动态变化，SLO 以 TTFT 与 TPOT 双指标约束；材料未给出具体批大小与 SLO 数值，仅说明按最大生成长度预留 page 数并以 page 为粒度调度。","部署配方：硬件档位为单机 HBM + host 内存 + NVMe 三级存储，并行拓扑未给出；量化方案未给出；KV 采用固定大小 page 的非连续分配，专家权重按热度分层驻留，热专家常驻 HBM、冷专家放 CPU/NVMe。","稳定性技巧为按访问频次统计专家热度并异步更新热度表、显存池水位超阈值时触发 KV page 换出或专家权重降级；失败模式是路由突然偏向冷专家时冷专家换入换出引入 host-device 拷贝，造成单 token 时延尖峰。","与相邻算法的差别：相比连续分配的 KV cache，它用 page table 间接寻址消除外部碎片；相比纯专家卸载方案，它把权重与 KV 放进统一显存池按 SLO 动态分配配额，而不是各自独立管理。","适用边界与规模上限：材料称显存利用率提升 20–40%，decode 阶段热专家命中率通常 >90%；page table 间接寻址使 attention kernel 地址计算更复杂，小 page 时 IO 效率下降，因此 page 过小会限制长上下文吞吐。"],"anchors":["20–40%",">90%"],"pitfalls":["路由分布突变使请求集中到被换出的冷专家，host-device 拷贝串行插入 decode 关键路径，单 token 时延出现尖峰并击穿 TPOT SLO。","page 尺寸标定过小导致 attention kernel 地址计算与 IO 效率下降，page table 间接寻址开销占比升高，长上下文请求吞吐反而低于连续分配方案。","统一显存池水位阈值设置不当，KV page 换出与专家权重降级频繁抖动，两者互相触发形成换入换出震荡，显存利用率提升被拷贝开销抵消。"]},{"id":"alg-spec-decode-moe","name":"MoE 投机解码","year":2022,"direction":"dir-disaggregated-pd","tier":"recent","problem":"MoE decode 阶段每 token 只激活少量专家，GPU 算力大量闲置而时延受权重读取带宽限制；自回归逐 token 生成无法利用这批闲置算力。","idea":"用一个小稠密 draft 模型或 MoE 自身的轻量头一次提议 γ 个 token，目标 MoE 模型并行验证这 γ 个 token，按拒绝采样接受最长前缀，把多次权重读取摊到多个 token 上。","how":"解决的具体问题是 MoE decode 阶段每 token 只激活少量专家，GPU 算力大量闲置而时延受权重读取带宽限制，自回归逐 token 生成无法利用这批闲置算力。 机制步骤按数据流为：draft 模型自回归生成 γ 个候选 token 及其概率 q；目标 MoE 模型对这 γ 个 token 做一次并行前向得到概率 p；逐位置按接受概率采样接受或拒绝，遇拒绝即截断；被接受 token 追加到 KV cache，被拒绝位置用目标分布重采样一个 token；全部接受则额外采一个 bonus token。 核心公式为逐位置接受概率 $$a_i = \\min\\left(1, \\frac{p_i}{q_i}\\right)$$，其中 $p_i$ 为目标 MoE 模型对第 $i$ 个候选 token 的概率、$q_i$ 为 draft 模型给出的概率；接受最长前缀后 KV cache 按接受长度批量追加，输出分布与目标模型严格一致。","flow":["draft 模型自回归生成 γ 个候选 token 及其概率 q","目标 MoE 模型对这 γ 个 token 做一次前向（并行验证），得到概率 p","逐位置计算接受概率 min(1, p/q)，采样接受/拒绝，遇到拒绝即截断","被接受的 token 追加到 KV cache，被拒绝位置用目标分布重采样一个 token","若全部接受则额外采一个 bonus token，KV cache 按接受长度批量追加"],"formula":"$$\\mathbb{E}[\\text{tokens/step}]=\\frac{1-\\alpha^{\\gamma+1}}{1-\\alpha},\\quad \\text{speedup}\\approx\\frac{\\mathbb{E}[\\text{tokens/step}]}{1+\\gamma\\,c_{\\text{draft}}/c_{\\text{target}}}$$","pros":["MoE 验证阶段并行处理 γ 个 token，专家权重只读一次，带宽受限的 decode 阶段可获得 2–3 倍加速","输出分布与目标模型严格一致（拒绝采样无偏），不损失质量"],"cons":["draft 模型本身有显存与计算开销，γ 过大时验证批次膨胀导致 MoE 路由负载不均、专家溢出","MoE 路由对 draft token 的专家选择与逐 token 生成不同，接受率低于稠密模型预期"],"papers":["paper-fast-inference-from-transformers-via-2022","paper-why-speculative-decoding-works-bette-2026"],"successors":["alg-moe-alltoall-ep"],"facts":["解决的具体问题是 MoE decode 阶段每 token 只激活少量专家，GPU 算力大量闲置而时延受权重读取带宽限制，自回归逐 token 生成无法利用这批闲置算力。","机制步骤按数据流为：draft 模型自回归生成 γ 个候选 token 及其概率 q；目标 MoE 模型对这 γ 个 token 做一次并行前向得到概率 p；逐位置按接受概率采样接受或拒绝，遇拒绝即截断；被接受 token 追加到 KV cache，被拒绝位置用目标分布重采样一个 token；全部接受则额外采一个 bonus token。","核心公式为逐位置接受概率 $$a_i = \\min\\left(1, \\frac{p_i}{q_i}\\right)$$，其中 $p_i$ 为目标 MoE 模型对第 $i$ 个候选 token 的概率、$q_i$ 为 draft 模型给出的概率；接受最长前缀后 KV cache 按接受长度批量追加，输出分布与目标模型严格一致。","负载配方：请求形态为在线低延迟 decode 服务，批大小因验证阶段一次并行处理 γ 个 token 而膨胀，SLO 以 TPOT 为主；材料未给出具体 γ、批大小与 SLO 数值，仅说明 γ 过大时验证批次膨胀导致 MoE 路由负载不均。","部署配方：硬件档位与并行拓扑未给出；量化方案未给出；KV 按接受长度批量追加而非逐 token 追加；draft 模型可为小稠密模型或 MoE 自身的轻量头，需额外占用显存与计算。","稳定性技巧为用拒绝采样保证输出无偏、按接受长度批量追加 KV 以减少碎片；失败模式是 γ 过大时验证批次膨胀使 MoE 路由负载不均、专家容量溢出，且 MoE 路由对 draft token 的专家选择与逐 token 生成不同，接受率低于稠密模型预期。","与相邻算法的差别：相比普通自回归 decode，它把多次权重读取摊到 γ 个 token 上以缓解带宽受限；相比稠密模型投机解码，MoE 验证阶段的路由按 token 独立计算，专家选择随 draft token 变化，接受率与专家负载分布均不同。","适用边界与规模上限：材料称带宽受限的 decode 阶段可获得 2–3 倍加速且不损失质量；但 draft 模型本身有显存与计算开销，γ 过大时验证批次膨胀与专家溢出会抵消收益，因此 γ 需按专家容量与带宽上限标定。"],"anchors":["2–3 倍"],"pitfalls":["γ 取值过大使验证批次远超 decode 常规批大小，MoE 路由分布偏斜导致热点专家容量溢出，验证前向被迫拆分或排队，加速比转为负收益。","draft 模型与目标 MoE 的路由偏好不一致，draft token 命中的专家与逐 token 生成路径不同，接受率显著低于稠密模型预期，验证算力被大量拒绝位置浪费。","被拒绝位置用目标分布重采样时若 KV 追加与截断处理不当，page 归还与批量追加交错造成 KV cache 长度与 page table 不一致，输出分布出现偏差。"]},{"id":"alg-chunked-prefill","name":"分块预填与解码 piggyback","year":2023,"direction":"dir-moe-routing-capacity","tier":"recent","problem":"长预填请求独占 GPU 造成 decode 请求被饿死，TTFT 与 TPOT 无法同时满足；预填与解码混批时预填的算力密集与解码的带宽密集相互干扰。","idea":"把长预填切成固定大小的 chunk，每个调度步把若干预填 chunk 与当前所有 decode 请求拼成一个批次，decode token 与预填 token 共享一次前向，用 chunk 大小控制预填对 decode 的干扰上限。","how":"解决的具体问题是长预填请求独占 GPU 造成 decode 请求被饿死，TTFT 与 TPOT 无法同时满足；预填的算力密集与解码的带宽密集在同一批次内相互干扰。 机制步骤按数据流为：预填请求按 chunk size（如 512 token）切分进入预填队列；调度器每步取出 decode 批次加一个预填 chunk 拼成统一批次；统一批次过 MoE 层，路由按 token 独立计算，预填 token 与 decode token 混合 dispatch；attention 对预填 token 用因果 mask、对 decode token 用 KV gather，输出按来源拆分；预填 chunk 完成后 KV 写入 page。 核心调度关系可写为 $$B_{\\text{step}} = B_{\\text{decode}} + c_{\\text{chunk}}$$，其中 $B_{\\text{decode}}$ 为当前 decode 请求 token 数、$c_{\\text{chunk}}$ 为每步注入的预填 chunk 大小；chunk 大小决定预填对 decode 的干扰上限，TTFT 与 TPOT 可分别通过 chunk size 调优。","flow":["预填请求按 chunk size（如 512 token）切分，进入预填队列","调度器每步取出 decode 批次 + 一个预填 chunk，拼成统一批次","统一批次过 MoE 层，路由按 token 独立计算，预填 token 与 decode token 混合 dispatch","attention 对预填 token 用因果 mask、对 decode token 用 KV gather，输出按来源拆分","预填 chunk 完成后 KV 写入 page，decode token 继续自回归，直到预填队列清空"],"formula":"$$T_{\\text{step}}\\approx\\max\\left(\\frac{B_{\\text{dec}}N_{\\text{kv}}}{\\text{BW}},\\ \\frac{B_{\\text{dec}}+C_{\\text{chunk}}}{\\text{FLOPs}_{\\text{peak}}}\\right),\\quad \\text{TPOT}\\le \\frac{T_{\\text{step}}}{\\text{tokens/step}}$$","pros":["decode 请求不再被长预填阻塞，TPOT 抖动显著降低，TTFT 与 TPOT 可通过 chunk size 分别调优","预填与解码共享一次权重读取，MoE 专家权重带宽被两类 token 共同摊薄，GPU 利用率提升"],"cons":["预填 chunk 与 decode 混批使 MoE 路由分布更偏斜，热点专家容量溢出概率上升","chunk 过小则预填 kernel launch 开销占比高，chunk 过大则 decode 被拖慢，需按 SLO 精细标定"],"papers":["paper-sarathi-efficient-llm-inference-by-p-2023","paper-deepspeed-fastgen-high-throughput-te-2024"],"successors":["alg-grouped-gemm-tcgen05"],"facts":["解决的具体问题是长预填请求独占 GPU 造成 decode 请求被饿死，TTFT 与 TPOT 无法同时满足；预填的算力密集与解码的带宽密集在同一批次内相互干扰。","机制步骤按数据流为：预填请求按 chunk size（如 512 token）切分进入预填队列；调度器每步取出 decode 批次加一个预填 chunk 拼成统一批次；统一批次过 MoE 层，路由按 token 独立计算，预填 token 与 decode token 混合 dispatch；attention 对预填 token 用因果 mask、对 decode token 用 KV gather，输出按来源拆分；预填 chunk 完成后 KV 写入 page。","核心调度关系可写为 $$B_{\\text{step}} = B_{\\text{decode}} + c_{\\text{chunk}}$$，其中 $B_{\\text{decode}}$ 为当前 decode 请求 token 数、$c_{\\text{chunk}}$ 为每步注入的预填 chunk 大小；chunk 大小决定预填对 decode 的干扰上限，TTFT 与 TPOT 可分别通过 chunk size 调优。","负载配方：请求形态为长预填与在线 decode 混合，批大小为 decode 批次加一个预填 chunk，SLO 同时约束 TTFT 与 TPOT；材料给出 chunk size 示例为 512 token，未给出具体批大小与 SLO 数值。","部署配方：硬件档位与并行拓扑未给出；量化方案未给出；KV 以 page 为单位写入，预填 chunk 完成后 KV 写入 page 供后续 decode gather；预填与解码共享一次权重读取以摊薄 MoE 专家权重带宽。","稳定性技巧为用 chunk size 控制预填对 decode 的干扰上限、按来源拆分输出以避免 mask 混淆；失败模式是 chunk 过小则预填 kernel launch 开销占比高，chunk 过大则 decode 被拖慢，混批使 MoE 路由分布更偏斜、热点专家容量溢出概率上升。","与相邻算法的差别：相比整段预填独占 GPU，它把长预填切块并与 decode 拼批以降低 TPOT 抖动；相比预填解码分离部署，它不拆分 GPU 池，预填与解码仍共享同一前向与同一份专家权重，靠 chunk 大小而非资源隔离来控制干扰。","适用边界与规模上限：材料称 decode 请求不再被长预填阻塞、TPOT 抖动显著降低且 GPU 利用率提升；但 chunk size 需按 SLO 精细标定，预填 chunk 与 decode 混批使路由偏斜，热点专家容量成为规模上限。"],"anchors":["512 token"],"pitfalls":["chunk size 标定过大使单步预填 token 数压过 decode 批次，decode 的 TPOT 被预填算力拖慢，长预填请求仍会周期性击穿延迟 SLO。","chunk size 过小使预填 kernel launch 开销占比升高，调度步数增多而每步有效 token 减少，GPU 利用率与 TTFT 同时恶化。","预填 token 与 decode token 混批后 MoE 路由分布偏斜，热点专家容量溢出触发 token 丢弃或排队，混合 dispatch 的负载不均放大专家并行通信开销。"]},{"id":"alg-pd-disaggregation","name":"预填解码分离部署","year":2024,"direction":"dir-expert-parallel-alltoall","tier":"recent","problem":"预填是算力密集、解码是带宽密集，二者混部在同一 GPU 上相互争抢资源，且 MoE 专家权重在两类负载下访问模式不同，导致 goodput 远低于峰值。","idea":"把预填与解码拆到不同 GPU 池：预填池跑大 batch 算力密集任务，解码池跑小 batch 带宽密集任务，KV cache 通过高速互联从预填池传到解码池，两池按各自 SLO 独立扩缩容。","how":"解决的具体问题是预填算力密集、解码带宽密集，二者混部在同一 GPU 上相互争抢资源，且 MoE 专家权重在两类负载下访问模式不同，导致 goodput 远低于峰值。 机制步骤按数据流为：请求先进入预填池按大 batch 做 chunked prefill 生成完整 KV cache；KV cache 通过 NVLink/IB 按 page 粒度流式传输到解码池目标 GPU；解码池接收 KV page 后开始自回归 decode，MoE 专家权重按解码池访问模式常驻；两池独立调度，预填池按 TTFT SLO 扩容、解码池按 TPOT SLO 扩容；请求结束后解码池释放 KV page。 核心容量关系可写为 $$R = \\frac{N_{\\text{prefill}}}{N_{\\text{decode}}}$$，其中 $N_{\\text{prefill}}$ 为预填池 GPU 数、$N_{\\text{decode}}$ 为解码池 GPU 数，比例需按流量离线规划；KV 传输时间与预填时间之比决定长上下文请求是否受互联带宽约束。","flow":["请求先进入预填池，按大 batch 做 chunked prefill，生成完整 KV cache","KV cache 通过 NVLink/IB 从预填池传输到解码池的目标 GPU，按 page 粒度流式传输","解码池接收 KV page 后开始自回归 decode，MoE 专家权重按解码池的访问模式常驻","预填池与解码池各自独立调度，预填池按 TTFT SLO 扩容、解码池按 TPOT SLO 扩容","请求结束后解码池释放 KV page，预填池继续处理新请求"],"formula":"$$\\text{goodput}=\\min\\left(\\frac{N_{\\text{pre}}\\cdot\\text{thr}_{\\text{pre}}}{\\text{TTFT}_{\\text{SLO}}},\\ \\frac{N_{\\text{dec}}\\cdot\\text{thr}_{\\text{dec}}}{\\text{TPOT}_{\\text{SLO}}}\\right),\\quad \\text{KV transfer}=\\frac{2LHK\\,d\\,N_{\\text{req}}}{\\text{BW}_{\\text{link}}}$$","pros":["预填与解码各自使用最优 batch 形状与并行策略，MoE 专家权重在解码池按带宽最优布局，goodput 相比混部提升 1.5–2 倍","两池可独立扩缩容，按 TTFT/TPOT 分别满足 SLO，资源不互相挤占"],"cons":["KV cache 跨池传输占用互联带宽，长上下文请求的 KV 传输时间可能超过预填本身","两池需要额外的路由与 KV 中转层，故障域扩大，预填池与解码池比例需按流量离线规划"],"papers":["paper-distserve-disaggregating-prefill-and-2024","paper-splitwise-efficient-generative-llm-i-2023"],"successors":["alg-moe-skew-adaptive-dispatch"],"facts":["解决的具体问题是预填算力密集、解码带宽密集，二者混部在同一 GPU 上相互争抢资源，且 MoE 专家权重在两类负载下访问模式不同，导致 goodput 远低于峰值。","机制步骤按数据流为：请求先进入预填池按大 batch 做 chunked prefill 生成完整 KV cache；KV cache 通过 NVLink/IB 按 page 粒度流式传输到解码池目标 GPU；解码池接收 KV page 后开始自回归 decode，MoE 专家权重按解码池访问模式常驻；两池独立调度，预填池按 TTFT SLO 扩容、解码池按 TPOT SLO 扩容；请求结束后解码池释放 KV page。","核心容量关系可写为 $$R = \\frac{N_{\\text{prefill}}}{N_{\\text{decode}}}$$，其中 $N_{\\text{prefill}}$ 为预填池 GPU 数、$N_{\\text{decode}}$ 为解码池 GPU 数，比例需按流量离线规划；KV 传输时间与预填时间之比决定长上下文请求是否受互联带宽约束。","负载配方：请求形态为在线生成服务，预填池跑大 batch 算力密集任务、解码池跑小 batch 带宽密集任务，SLO 由预填池承担 TTFT、解码池承担 TPOT；材料未给出具体批大小、池比例与 SLO 数值。","部署配方：硬件档位为预填池与解码池两组 GPU，互联为 NVLink/IB；并行拓扑按两池各自最优 batch 形状与并行策略配置，材料未给出具体并行度；量化方案未给出；KV 按 page 粒度流式跨池传输。","稳定性技巧为两池按各自 SLO 独立扩缩容、KV 按 page 流式传输以重叠传输与计算；失败模式是长上下文请求的 KV 传输时间可能超过预填本身，且两池需额外路由与 KV 中转层，故障域扩大。","与相邻算法的差别：相比分块预填与解码 piggyback，它把预填与解码拆到不同 GPU 池实现资源隔离，而非在同一批次内混合；代价是引入 KV 跨池传输与额外中转层，而 piggyback 不占用互联带宽。","适用边界与规模上限：材料称 goodput 相比混部提升 1.5–2 倍且两池可独立扩缩容满足 TTFT/TPOT SLO；但预填池与解码池比例需按流量离线规划，KV 传输受互联带宽上限约束，长上下文请求的传输时间可能超过预填本身。"],"anchors":["1.5–2 倍"],"pitfalls":["长上下文请求的 KV cache 跨池传输时间超过预填本身，解码池等待 KV page 到达而空转，TTFT 与 TPOT 同时恶化且互联带宽成为瓶颈。","预填池与解码池比例按离线流量规划后遇流量形态突变，一池空闲一池排队，独立扩缩容滞后导致 goodput 低于混部方案。","KV 中转层与路由层引入额外故障域，page 粒度流式传输在链路抖动时出现部分 page 丢失或重复，解码池 KV 长度与预填池不一致导致输出错乱。"]},{"id":"alg-disagg-expert-parallel","name":"分离式专家并行","year":2025,"direction":"dir-grouped-gemm-tcgen05","tier":"recent","problem":"传统专家并行把专家权重切分到所有 GPU，每层两次 All-to-All 同步，decode 时通信时延占比高；预填与解码对专家并行的通信模式需求不同，统一 EP 无法同时优化。","idea":"把专家池从注意力层解耦为独立的专家服务集群，注意力 GPU 通过 All-to-All 把 token 发给专家集群，专家集群内部按专家并行计算后回传，预填与解码可各自选择 EP 度数与通信拓扑。","how":"解决的问题：传统专家并行把专家权重切分到所有 GPU，每层需要两次 All-to-All 同步，decode 阶段通信时延占比高；且预填与解码对专家并行的通信模式需求不同，统一 EP 无法同时优化两者。 机制步骤一：注意力层 GPU 完成路由计算，把 token 及其路由权重打包为 dispatch 消息，经 RDMA 发往独立专家集群，并按专家 ID 路由到对应专家所在 GPU。 机制步骤二：专家集群内以分组 GEMM 计算，结果按原 token 索引打包为 combine 消息回传到发起 GPU，按路由权重加权合并后进入下一层。","flow":["注意力层 GPU 计算路由，把 token 及其路由权重打包为 dispatch 消息","dispatch 消息通过 RDMA 发往专家集群，按专家 ID 路由到对应专家所在 GPU","专家集群内分组 GEMM 计算，结果按原 token 索引打包为 combine 消息","combine 消息回传到发起 GPU，按路由权重加权合并，进入下一层","预填阶段用大 EP 度数摊薄权重读取，解码阶段用小 EP 度数降低通信跳数"],"formula":"$$T_{\\text{layer}}=T_{\\text{attn}}+\\underbrace{\\frac{S_{\\text{token}}\\,N_{\\text{token}}}{\\text{BW}_{\\text{link}}}}_{T_{\\text{dispatch}}}+T_{\\text{gemm}}+\\underbrace{\\frac{S_{\\text{out}}\\,N_{\\text{token}}}{\\text{BW}_{\\text{link}}}}_{T_{\\text{combine}}},\\quad \\text{EP}_{\\text{opt}}=\\arg\\min_{\\text{EP}}\\left(T_{\\text{gemm}}(\\text{EP})+T_{\\text{comm}}(\\text{EP})\\right)$$","pros":["专家集群独立扩缩容，注意力层与专家层可按各自瓶颈分别优化，decode 通信跳数降低","预填与解码可使用不同 EP 度数，避免统一 EP 下解码被过度通信拖慢"],"cons":["token 跨集群往返引入额外网络跳数与序列化开销，小 batch decode 时通信时延可能超过 GEMM","专家集群故障会阻塞所有注意力 GPU，需要复杂的容错与重路由机制"],"papers":["paper-megascale-infer-serving-mixture-of-e-2025","paper-mooncake-a-kvcache-centric-disaggreg-2024"],"successors":[],"facts":["解决的问题：传统专家并行把专家权重切分到所有 GPU，每层需要两次 All-to-All 同步，decode 阶段通信时延占比高；且预填与解码对专家并行的通信模式需求不同，统一 EP 无法同时优化两者。","机制步骤一：注意力层 GPU 完成路由计算，把 token 及其路由权重打包为 dispatch 消息，经 RDMA 发往独立专家集群，并按专家 ID 路由到对应专家所在 GPU。","机制步骤二：专家集群内以分组 GEMM 计算，结果按原 token 索引打包为 combine 消息回传到发起 GPU，按路由权重加权合并后进入下一层。","核心公式：dispatch 消息量可写为 $$M_{\\text{disp}} = N_{\\text{tok}} \\times k \\times (d_{\\text{model}} + w_{\\text{route}})$$，其中 $N_{\\text{tok}}$ 为 token 数、$k$ 为 top-k、$d_{\\text{model}}$ 为隐藏维、$w_{\\text{route}}$ 为路由权重字节数；combine 消息量同阶。","负载配方：预填阶段用大 EP 度数摊薄专家权重读取，解码阶段用小 EP 度数降低通信跳数；请求形态为长预填加短解码的自回归服务，批大小按 SLO 调节，材料未给出具体批大小与 SLO 数值。","部署配方：注意力 GPU 与专家集群分离部署，跨集群走 RDMA；专家集群内部按专家并行分组 GEMM，量化与 KV cache 压缩细节材料未给出。","稳定性技巧与失败模式：专家集群故障会阻塞所有注意力 GPU，需容错与重路由机制；小 batch decode 时跨集群往返的额外网络跳数与序列化开销可能超过 GEMM 计算时间。","与相邻算法差别：相比统一 EP，本方法把专家池从注意力层解耦为独立服务集群，可独立扩缩容，并允许预填与解码各自选择 EP 度数与通信拓扑。","适用边界：适合预填与解码通信需求差异大、专家层成为独立瓶颈的大规模 MoE 服务；规模上限受跨集群网络跳数与序列化开销约束，小 batch decode 场景收益递减。"],"anchors":["paper-megascale-infer-serving-mixture-of-e-2025","paper-mooncake-a-kvcache-centric-disaggreg-2024"],"pitfalls":["专家集群故障会阻塞所有注意力 GPU，缺乏重路由时整个服务停摆。","小 batch decode 下跨集群往返时延可能超过分组 GEMM，抵消解耦收益。","预填与解码 EP 度数配置不当会造成专家集群负载倾斜与显存预留浪费。"]},{"id":"alg-monomoe-fused-kernel","name":"量化 MoE 解码融合大核","year":2026,"direction":"dir-nvfp4-fp8-quant","tier":"recent","problem":"量化 MoE decode 时路由、dispatch、反量化、分组 GEMM、combine 被拆成多个 kernel，每个 kernel 都要读写中间缓冲，kernel launch 与 HBM 往返开销在小 batch 下占比超过 50%。","idea":"把路由后的 dispatch、NVFP4/INT4 反量化、分组 GEMM、combine 融合为单个 persistent mega-kernel，中间结果留在 shared memory / 寄存器，用 tcgen05 异步 MMA 与 TMA 重叠权重加载。","how":"解决的问题：量化 MoE decode 时路由、dispatch、反量化、分组 GEMM、combine 被拆成多个 kernel，每个 kernel 都要读写中间缓冲，小 batch 下 kernel launch 与 HBM 往返开销占比超过 50%。 机制步骤一：mega-kernel 启动后常驻 SM，从全局队列取 micro-batch 的路由结果，避免重复 launch。 机制步骤二：TMA 异步把激活专家的量化权重从 HBM 加载到 shared memory，与 tcgen05 异步 MMA 流水重叠；在 shared memory 内完成反量化与 token 重排后直接喂给 MMA。","flow":["mega-kernel 启动后常驻 SM，从全局队列取 micro-batch 的路由结果","TMA 异步把激活专家的量化权重从 HBM 加载到 shared memory，与 MMA 流水重叠","在 shared memory 内完成反量化与 token 重排，直接喂给 tcgen05 MMA","MMA 结果在寄存器内按路由权重累加，combine 不落 HBM","输出写回全局显存，kernel 继续处理下一 micro-batch，避免重复 launch"],"formula":"$$T_{\\text{decode}}\\approx\\max\\left(\\frac{\\sum_e |W_e|\\cdot b_w}{\\text{BW}},\\ \\frac{\\text{FLOPs}}{\\text{FLOPs}_{\\text{peak}}}\\right)+\\epsilon_{\\text{launch}},\\quad \\epsilon_{\\text{launch}}\\to 0\\ \\text{(persistent)}$$","pros":["消除 kernel 间 HBM 往返与 launch 开销，小 batch decode 时延可降低 30–50%","TMA 与 tcgen05 异步流水重叠权重加载与 MMA，带宽受限场景下 GPU 利用率接近峰值"],"cons":["mega-kernel 实现复杂度极高，需手写 PTX/CUDA 并针对 SM100/SM103 的 TMA 与 tcgen05 指令定制","融合后调试与 profiling 困难，路由分布突变时难以定位是哪个阶段退化"],"papers":["paper-monomoe-an-efficient-fused-mega-kern-2026","paper-sonicmoe-accelerating-moe-with-io-an-2025"],"successors":[],"facts":["解决的问题：量化 MoE decode 时路由、dispatch、反量化、分组 GEMM、combine 被拆成多个 kernel，每个 kernel 都要读写中间缓冲，小 batch 下 kernel launch 与 HBM 往返开销占比超过 50%。","机制步骤一：mega-kernel 启动后常驻 SM，从全局队列取 micro-batch 的路由结果，避免重复 launch。","机制步骤二：TMA 异步把激活专家的量化权重从 HBM 加载到 shared memory，与 tcgen05 异步 MMA 流水重叠；在 shared memory 内完成反量化与 token 重排后直接喂给 MMA。","机制步骤三：MMA 结果在寄存器内按路由权重累加，combine 不落 HBM，输出写回全局显存后 kernel 继续处理下一 micro-batch。","核心公式：融合后时延近似 $$T_{\\text{fused}} \\approx \\max\\left(\\frac{B_w}{\\text{BW}_{\\text{HBM}}},\\ T_{\\text{MMA}}\\right) + T_{\\text{epilogue}}$$，其中 $B_w$ 为权重字节数、$\\text{BW}_{\\text{HBM}}$ 为显存带宽、$T_{\\text{MMA}}$ 为矩阵乘时间、$T_{\\text{epilogue}}$ 为寄存器累加与写回时间。","负载配方：面向小 batch decode 场景，micro-batch 从全局队列逐个取；材料未给出具体批大小与 SLO 数值。","部署配方：针对 SM100/SM103 的 TMA 与 tcgen05 指令定制，权重为 NVFP4/INT4 量化格式，激活量化细节材料未给出。","稳定性技巧与失败模式：融合后调试与 profiling 困难，路由分布突变时难以定位是哪个阶段退化；需手写 PTX/CUDA 并针对特定架构指令定制。","与相邻算法差别：相比多 kernel 流水，本方法把 dispatch、反量化、分组 GEMM、combine 融合为单个 persistent mega-kernel，中间结果留在 shared memory/寄存器。","适用边界：适合小 batch、带宽受限的量化 MoE decode；收益随 batch 增大而下降，因为大 batch 下 GEMM 计算占比上升、launch 开销被摊薄。"],"anchors":["paper-monomoe-an-efficient-fused-mega-kern-2026","paper-sonicmoe-accelerating-moe-with-io-an-2025"],"pitfalls":["mega-kernel 需手写 PTX/CUDA 并绑定 SM100/SM103 指令，跨架构移植成本极高。","融合后调试与 profiling 困难，路由分布突变时无法定位退化阶段。","shared memory 容量不足时反量化与 token 重排会溢出到 HBM，抵消融合收益。"]},{"id":"alg-moe-capacity-router","name":"容量因子路由与令牌丢弃","year":2021,"direction":"dir-kv-cache-compression","tier":"classic","problem":"MoE 层中专家负载天然不均衡，热门专家过载导致 All-to-All 与分组 GEMM 出现长尾，冷门专家算力闲置，单卡显存与通信带宽被少数专家拖垮。","idea":"为每个专家设定容量上限 capacity = ceil(N_tokens × top_k / N_experts × CF)，超出容量的令牌直接丢弃或走残差旁路，用容量因子 CF 在负载均衡与精度之间做显式权衡。","how":"解决的问题：MoE 层专家负载天然不均衡，热门专家过载导致 All-to-All 与分组 GEMM 出现长尾，冷门专家算力闲置，单卡显存与通信带宽被少数专家拖垮。 机制步骤一：对每个 token 计算 router logits 并取 top-k 专家索引，按专家统计被选中的 token 数并与容量上限比较。 机制步骤二：超出容量的 token 从该专家队列中剔除，按位置填充零或走残差旁路；保留的 token 按专家分组打包成连续 token 块。","flow":["对每个 token 计算 router logits 并取 top-k 专家索引","按专家统计被选中的 token 数，与 capacity 比较","超出容量的 token 从该专家队列中剔除，按位置填充零或走残差","将保留下来的 token 按专家分组，打包成连续 token 块","分组 GEMM 在 tcgen05 上按专家块执行，输出按原 token 位置散射回序列"],"formula":"$$\\text{capacity}=\\left\\lceil \\frac{T\\cdot k}{E}\\cdot \\text{CF}\\right\\rceil,\\quad \\text{drop}_e=\\max(0,\\,n_e-\\text{capacity})$$","pros":["把 All-to-All 通信量和分组 GEMM 的 tile 数硬性封顶，长尾延迟可预测","容量因子是单一可调旋钮，服务端可按 SLO 在吞吐与精度间连续调节"],"cons":["丢弃令牌直接损失信息，CF<1.5 时在长尾分布上精度下降明显","CF 设大则显存与通信按最坏情况预留，GPU 利用率被拉低"],"papers":["paper-switch-transformers-scaling-to-trill-2021","paper-gshard-scaling-giant-models-with-con-2020"],"successors":["alg-paged-kv-moe"],"facts":["解决的问题：MoE 层专家负载天然不均衡，热门专家过载导致 All-to-All 与分组 GEMM 出现长尾，冷门专家算力闲置，单卡显存与通信带宽被少数专家拖垮。","机制步骤一：对每个 token 计算 router logits 并取 top-k 专家索引，按专家统计被选中的 token 数并与容量上限比较。","机制步骤二：超出容量的 token 从该专家队列中剔除，按位置填充零或走残差旁路；保留的 token 按专家分组打包成连续 token 块。","机制步骤三：分组 GEMM 在 tcgen05 上按专家块执行，输出按原 token 位置散射回序列。","核心公式：容量定义为 $$\\text{capacity} = \\left\\lceil \\frac{N_{\\text{tokens}} \\times k}{N_{\\text{experts}}} \\times \\text{CF} \\right\\rceil$$，其中 $N_{\\text{tokens}}$ 为令牌数、$k$ 为 top-k、$N_{\\text{experts}}$ 为专家数、$\\text{CF}$ 为容量因子。","负载配方：服务端按 SLO 在吞吐与精度间连续调节 CF；材料未给出具体请求形态、批大小与 SLO 数值。","部署配方：分组 GEMM 在 tcgen05 上执行，容量上限硬性封顶 All-to-All 通信量与 tile 数；量化与 KV cache 细节材料未给出。","稳定性技巧与失败模式：CF<1.5 时在长尾分布上精度下降明显；CF 设大则显存与通信按最坏情况预留，GPU 利用率被拉低。","与相邻算法差别：相比专家选择路由，本方法保持 token-choice 方向，用容量因子事后截断，负载均衡是统计保证而非算法保证。","适用边界：适合负载分布相对平稳、可接受少量令牌丢弃的训练与推理场景；长尾极端的分布下精度损失显著，规模上限受最坏情况显存预留约束。"],"anchors":["paper-switch-transformers-scaling-to-trill-2021","paper-gshard-scaling-giant-models-with-con-2020"],"pitfalls":["CF<1.5 时长尾分布上令牌丢弃造成明显精度下降。","CF 设大导致显存与通信按最坏情况预留，GPU 利用率被拉低。","热门专家过载时 All-to-All 与分组 GEMM 长尾仍可能突破 SLO。"]},{"id":"alg-moe-alltoall-ep","name":"专家并行 All-to-All 调度","year":2024,"direction":"dir-disaggregated-pd","tier":"recent","problem":"MoE 专家分散在多卡/多节点，token 需跨设备搬运到目标专家所在 GPU，All-to-All 的带宽与延迟成为解码阶段的主要瓶颈，且与分组 GEMM 串行导致流水线空转。","idea":"将 token 按目标专家 rank 分桶，用 NVLink/NVSwitch 的 All-to-All 与分组 GEMM 做通信-计算重叠，结合 DeepEP 的低延迟模式在解码小 batch 下走纯 NVLink 路径。","how":"解决的问题是 MoE 专家分散在多卡或多节点后，token 必须跨设备搬运到目标专家所在 GPU，All-to-All 的带宽与延迟在解码阶段成为主要瓶颈，且通信与分组 GEMM 串行执行导致流水线空转。 机制按数据流顺序为：router 产出 token 到专家的映射，按目标 rank 聚合为发送缓冲；All-to-All dispatch 把 token 及其元数据发往专家所在 rank；接收端按本地专家分组后用 tcgen05 分组 GEMM 计算；All-to-All combine 把专家输出送回原 token 所在 rank；最后按原 token 位置加权求和写回 KV/激活缓冲。 核心公式可写为 $$y_t=\\sum_{e\\in\\mathrm{TopK}(t)} g_{t,e}\\,\\mathrm{GEMM}_e(x_t)$$，其中 $g_{t,e}$ 为 router 门控权重，$x_t$ 为 token 激活，$\\mathrm{GEMM}_e$ 为专家 $e$ 的本地分组矩阵乘；跨 rank 时 $x_t$ 需先经 All-to-All dispatch 搬到 $e$ 所在设备。","flow":["router 产出 token→专家映射，按目标 rank 聚合为发送缓冲","All-to-All dispatch 将 token 及其元数据发往专家所在 rank","接收端按本地专家分组，tcgen05 分组 GEMM 计算","All-to-All combine 将专家输出送回原 token 所在 rank","按原 token 位置加权求和，写回 KV/激活缓冲"],"formula":"$$T_{\\text{layer}}=\\max\\left(T_{\\text{dispatch}},\\,T_{\\text{GEMM}}\\right)+T_{\\text{combine}},\\quad T_{\\text{dispatch}}=\\frac{2\\,S\\,k\\,d}{B_{\\text{NVLink}}}$$","pros":["dispatch 与 GEMM 重叠后，解码阶段 MoE 层时延可压到接近纯计算时间","DeepEP 低延迟模式在 NVLink 域内避免走 IB，小 batch 解码收益显著"],"cons":["跨节点 IB All-to-All 带宽远低于 NVLink，专家放置不当会放大跨域流量","combine 阶段必须等所有专家完成，最慢 rank 决定整层时延"],"papers":["paper-deepseek-v3-technical-report-2024","paper-megascale-infer-serving-mixture-of-e-2025"],"successors":["alg-moe-expert-cache-prefetch"],"facts":["解决的问题是 MoE 专家分散在多卡或多节点后，token 必须跨设备搬运到目标专家所在 GPU，All-to-All 的带宽与延迟在解码阶段成为主要瓶颈，且通信与分组 GEMM 串行执行导致流水线空转。","机制按数据流顺序为：router 产出 token 到专家的映射，按目标 rank 聚合为发送缓冲；All-to-All dispatch 把 token 及其元数据发往专家所在 rank；接收端按本地专家分组后用 tcgen05 分组 GEMM 计算；All-to-All combine 把专家输出送回原 token 所在 rank；最后按原 token 位置加权求和写回 KV/激活缓冲。","核心公式可写为 $$y_t=\\sum_{e\\in\\mathrm{TopK}(t)} g_{t,e}\\,\\mathrm{GEMM}_e(x_t)$$，其中 $g_{t,e}$ 为 router 门控权重，$x_t$ 为 token 激活，$\\mathrm{GEMM}_e$ 为专家 $e$ 的本地分组矩阵乘；跨 rank 时 $x_t$ 需先经 All-to-All dispatch 搬到 $e$ 所在设备。","负载配方：面向解码阶段小 batch 请求，batch 内 token 数少、每 token 仅激活 TopK 个专家，SLO 以单 token 时延（TPOT）为主；DeepEP 低延迟模式在 NVLink 域内避免走 IB，小 batch 解码收益显著。","部署配方：硬件档位为 NVLink/NVSwitch 互联的多卡节点，专家并行拓扑按专家放置划分 rank；NVLink 域内走纯 NVLink All-to-All，跨节点才回落 IB；量化与 KV 压缩与该调度正交，可叠加 NVFP4 权重与分层 KV。","稳定性技巧是让 dispatch 与分组 GEMM 重叠以隐藏通信，并把专家放置约束在 NVLink 域内以减少跨域流量；失败模式是专家放置不当放大跨节点 IB 流量，以及 combine 阶段必须等所有专家完成、最慢 rank 决定整层时延。","与逐专家独立 launch 的朴素实现相比，它把通信与计算做成可重叠的流水，而不是先全量 dispatch 再串行 GEMM；与纯张量并行相比，它按 token 的目标专家做稀疏搬运，只搬被路由到的 token 而非全量激活。","适用边界是多卡/多节点 MoE 解码，规模上限受 NVLink 域大小与 IB 带宽约束：域内 rank 越多收益越明显，跨域比例上升后 All-to-All 延迟会吞掉重叠收益；材料未给出具体带宽数字。"],"anchors":["paper-deepseek-v3-technical-report-2024","paper-megascale-infer-serving-mixture-of-e-2025"],"pitfalls":["专家放置不当会使大量 token 跨节点走 IB，All-to-All 带宽远低于 NVLink，解码时延被通信主导而非计算主导。","combine 阶段需等待所有专家 rank 完成，任一慢 rank 都会拖住整层，形成木桶效应式的流水线停顿。","小 batch 下若误走 IB 路径而非 NVLink 低延迟模式，通信固定开销占比过高，重叠设计失效。"]},{"id":"alg-grouped-gemm-tcgen05","name":"tcgen05 分组 GEMM 专家批处理","year":2024,"direction":"dir-moe-routing-capacity","tier":"recent","problem":"MoE 每个专家是独立的小矩阵乘，逐专家 launch 导致 kernel 启动开销与 tile 利用率低下，Blackwell 的 tcgen05 张量核心需要足够大的 M 维才能打满。","idea":"把所有专家的 token 块拼成一个大 M 维的 grouped GEMM，用 tcgen05 的 2-SM 协作与 TMEM 累加器按专家分段执行，一次 launch 覆盖全部专家。","how":"解决的问题是 MoE 每个专家是独立小矩阵乘，逐专家 launch 带来 kernel 启动开销与 tile 利用率低下，而 Blackwell 的 tcgen05 张量核心需要足够大的 M 维才能打满算力。 机制步骤：收集各专家 token 块并记录每段偏移与长度；按专家顺序拼接为统一 A 矩阵（$M_{total}\\times K$）；tcgen05 MMA 按段切换 B 权重指针、TMEM 累加器分段清零；每段完成后写回对应 token 输出缓冲；释放 TMEM 与共享内存进入下一层。 核心公式为分段矩阵乘 $$Y[m_s:m_{s+1},:]=A[m_s:m_{s+1},:]\\cdot B_s$$，其中 $m_s$ 为第 $s$ 个专家 token 段的起止偏移，$B_s$ 为该专家权重，$A$ 为拼接后的统一激活矩阵，累加器驻留 TMEM。","flow":["收集各专家 token 块，记录每段偏移与长度","按专家顺序拼接为统一 A 矩阵（M_total×K）","tcgen05 MMA 按段切换 B 权重指针，TMEM 累加器分段清零","每段完成后将结果写回对应 token 的输出缓冲","释放 TMEM 与共享内存，进入下一层"],"formula":"$$\\text{Util}=\\frac{\\sum_e M_e}{E\\cdot\\lceil \\max_e M_e/\\text{tile}_M\\rceil\\cdot \\text{tile}_M},\\quad \\text{GEMM 吞吐}\\propto \\text{Util}\\cdot\\text{TC 峰值}$$","pros":["单 kernel 覆盖全部专家，消除逐专家 launch 的 CPU 开销与流水线气泡","tcgen05 的 2-SM 模式让单专家 M 维较小时仍能打满张量核心"],"cons":["专家 token 数差异大时 tile 尾部浪费严重，Util 可能低于 50%","需要为每段维护偏移表，寄存器与共享内存压力随专家数线性增长"],"papers":["paper-monomoe-an-efficient-fused-mega-kern-2026","paper-sonicmoe-accelerating-moe-with-io-an-2025"],"successors":["alg-moe-prefetch-dual-phase"],"facts":["解决的问题是 MoE 每个专家是独立小矩阵乘，逐专家 launch 带来 kernel 启动开销与 tile 利用率低下，而 Blackwell 的 tcgen05 张量核心需要足够大的 M 维才能打满算力。","机制步骤：收集各专家 token 块并记录每段偏移与长度；按专家顺序拼接为统一 A 矩阵（$M_{total}\\times K$）；tcgen05 MMA 按段切换 B 权重指针、TMEM 累加器分段清零；每段完成后写回对应 token 输出缓冲；释放 TMEM 与共享内存进入下一层。","核心公式为分段矩阵乘 $$Y[m_s:m_{s+1},:]=A[m_s:m_{s+1},:]\\cdot B_s$$，其中 $m_s$ 为第 $s$ 个专家 token 段的起止偏移，$B_s$ 为该专家权重，$A$ 为拼接后的统一激活矩阵，累加器驻留 TMEM。","负载配方：面向 MoE 层内多专家并发的批处理场景，batch 内 token 按 router 分配到各专家，SLO 关注单层 GEMM 时延；专家 token 数差异大时 tile 尾部浪费明显。","部署配方：硬件档位为 Blackwell，使用 tcgen05 的 2-SM 协作模式与 TMEM 累加器；并行拓扑上每个专家段可跨 2 个 SM 协作以在小 M 维下打满张量核心；量化可与 NVFP4/FP8 权重叠加。","稳定性技巧是用偏移表管理各专家段并让 2-SM 模式补偿小 M 维；失败模式是专家 token 数差异大时 tile 尾部浪费严重、Util 可能低于 50%，以及偏移表使寄存器与共享内存压力随专家数线性增长。","与逐专家 launch 相比，它用单 kernel 覆盖全部专家，消除 CPU 启动开销与流水线气泡；与普通 grouped GEMM 相比，它利用 tcgen05 的 2-SM 协作与 TMEM 分段累加，在单专家 M 维较小时仍能打满张量核心。","适用边界是专家数多、单专家 token 块偏小的 MoE 层；规模上限受共享内存与寄存器约束，专家数增大时偏移表开销线性上升，材料未给出具体专家数上限。"],"anchors":["paper-monomoe-an-efficient-fused-mega-kern-2026","paper-sonicmoe-accelerating-moe-with-io-an-2025"],"pitfalls":["专家 token 数分布极度不均时，拼接矩阵的 tile 尾部大量空转，张量核心利用率可能跌破 50%。","专家数增多使偏移表与段元数据膨胀，寄存器与共享内存压力线性增长，可能触发占用率下降。","分段切换 B 权重指针与 TMEM 清零若同步不当，会在段间插入气泡，抵消单 kernel 融合的收益。"]},{"id":"alg-nvfp4-moe-weights","name":"NVFP4 权重与激活量化","year":2023,"direction":"dir-expert-parallel-alltoall","tier":"recent","problem":"MoE 参数量巨大，权重显存占用使单卡放不下全部专家，HBM 带宽成为解码阶段读取专家的瓶颈，FP8 仍不够省。","idea":"用 MXFP4/NVFP4 微缩放格式把专家权重压到 4 bit，每 16 或 32 个元素共享一个 E8M0 缩放因子，激活侧用 FP8 或 NVFP4，tcgen05 直接支持 FP4 MMA。","how":"解决的问题是 MoE 参数量巨大导致权重显存占用使单卡放不下全部专家，HBM 带宽成为解码阶段读取专家的瓶颈，FP8 仍不够省。 机制步骤：离线将专家权重按 block 量化到 NVFP4 并存缩放因子；解码时按 router 选中的专家加载对应 4-bit 权重块；激活按 token 动态量化到 FP8/NVFP4 并附带缩放；tcgen05 FP4 MMA 执行分组 GEMM、累加器保持 FP32；反量化缩放后写回进入下一层。 核心公式为微缩放量化 $$w\\approx s\\cdot q,\\quad s=2^{e-127}$$，其中 $q$ 为 4-bit 量化值，$s$ 为每 16 或 32 个元素共享的 E8M0 缩放因子，$e$ 为指数字段；反量化时 $\\hat{w}=s\\cdot q$ 参与 MMA。","flow":["离线将专家权重按 block 量化到 NVFP4，存缩放因子","解码时按 router 选中的专家加载对应 4-bit 权重块","激活按 token 动态量化到 FP8/NVFP4 并附带缩放","tcgen05 FP4 MMA 执行分组 GEMM，累加器保持 FP32","反量化缩放后写回，进入下一层"],"formula":"$$w_q=\\text{round}\\left(\\frac{w}{s}\\right),\\ s=\\frac{\\max|w_{\\text{block}}|}{\\text{FP4\\_MAX}},\\quad \\text{误差}\\ \\epsilon\\le \\frac{s}{2}\\ \\text{每元素}$$","pros":["专家权重显存降到 FP16 的 1/4，单卡可容纳更多专家，减少跨卡 All-to-All","tcgen05 原生 FP4 MMA，算力密度翻倍，解码带宽瓶颈显著缓解"],"cons":["4-bit 量化在长尾专家上误差累积，需要敏感层回退到 FP8","缩放因子带来额外元数据读取，block 太小时带宽收益被抵消"],"papers":["paper-microscaling-data-formats-for-deep-l-2023","paper-hardware-native-joint-sparse-quantiz-2026"],"successors":["alg-pd-disaggregation"],"facts":["解决的问题是 MoE 参数量巨大导致权重显存占用使单卡放不下全部专家，HBM 带宽成为解码阶段读取专家的瓶颈，FP8 仍不够省。","机制步骤：离线将专家权重按 block 量化到 NVFP4 并存缩放因子；解码时按 router 选中的专家加载对应 4-bit 权重块；激活按 token 动态量化到 FP8/NVFP4 并附带缩放；tcgen05 FP4 MMA 执行分组 GEMM、累加器保持 FP32；反量化缩放后写回进入下一层。","核心公式为微缩放量化 $$w\\approx s\\cdot q,\\quad s=2^{e-127}$$，其中 $q$ 为 4-bit 量化值，$s$ 为每 16 或 32 个元素共享的 E8M0 缩放因子，$e$ 为指数字段；反量化时 $\\hat{w}=s\\cdot q$ 参与 MMA。","负载配方：面向显存受限的解码场景，batch 大小受专家权重驻留量约束，SLO 以 TPOT 与并发数为目标；专家权重压到 4 bit 后单卡可容纳更多专家，减少跨卡 All-to-All。","部署配方：硬件档位为支持 tcgen05 原生 FP4 MMA 的 Blackwell；量化方案为权重 NVFP4、激活 FP8 或 NVFP4，累加器 FP32；并行拓扑上更多专家可驻留单卡，从而缩小专家并行域。","稳定性技巧是对量化敏感层回退到 FP8 以抑制长尾专家误差累积；失败模式是 4-bit 量化在长尾专家上误差累积，以及缩放因子带来额外元数据读取、block 太小时带宽收益被抵消。","与 FP8 量化相比，它把专家权重显存降到 FP16 的 1/4，并利用 tcgen05 原生 FP4 MMA 使算力密度翻倍；与整张量统一量化相比，它按 block 共享 E8M0 缩放因子，保留局部动态范围。","适用边界是显存与带宽受限的 MoE 解码；规模上限受量化误差约束，长尾专家与敏感层需要回退 FP8，材料未给出具体精度下降数字。"],"anchors":["paper-microscaling-data-formats-for-deep-l-2023","paper-hardware-native-joint-sparse-quantiz-2026"],"pitfalls":["长尾专家样本少，4-bit 量化误差在其上累积，可能导致路由到这些专家的 token 输出明显偏移。","缩放因子元数据随 block 变小而增多，额外读取开销可能抵消 4-bit 权重带来的带宽节省。","敏感层未回退 FP8 时，FP4 激活量化误差会在多层叠加后放大，破坏生成质量。"]},{"id":"alg-moe-kv-compress","name":"MoE KV cache 分层压缩","year":2023,"direction":"dir-grouped-gemm-tcgen05","tier":"recent","problem":"MoE 模型层数多、注意力头多，长上下文下 KV cache 显存超过专家权重，成为 batch size 与并发数的硬约束，PagedAttention 的分页只解决碎片不解决容量。","idea":"对 KV cache 按头/层做非对称量化与低秩压缩，冷 token 的 KV 换出到 CPU/NVMe，热 token 保留在 HBM，配合分页管理按需换入。","how":"解决的问题是 MoE 模型层数多、注意力头多，长上下文下 KV cache 显存超过专家权重，成为 batch size 与并发数的硬约束，PagedAttention 的分页只解决碎片不解决容量。 机制步骤：prefill 阶段按页写入 KV 并标记每页热度；解码时按注意力分数识别冷页并异步换出到 host 内存；换入时按需预取并与当前层计算重叠；对保留页做 INT8/FP8 KV 量化、缩放因子随页存储；注意力计算读取压缩 KV、反量化后进入 FlashAttention 流水。 核心公式为压缩 KV 的注意力 $$\\mathrm{Attn}(q,K,V)=\\mathrm{softmax}\\!\\left(\\frac{q\\hat{K}^{\\top}}{\\sqrt{d}}\\right)\\hat{V}$$，其中 $\\hat{K},\\hat{V}$ 为反量化后的键值，缩放因子随页存储，$d$ 为头维度。","flow":["prefill 阶段按页写入 KV，标记每页热度","解码时按注意力分数识别冷页，异步换出到 host 内存","换入时按需预取，与当前层计算重叠","对保留页做 INT8/FP8 KV 量化，缩放因子随页存储","注意力计算读取压缩 KV，反量化后进入 FlashAttention 流水"],"formula":"$$M_{\\text{KV}}=2\\cdot L\\cdot H\\cdot d_h\\cdot S\\cdot b_{\\text{elem}}\\cdot \\text{batch},\\quad \\text{压缩后}\\ M'_{\\text{KV}}=\\alpha M_{\\text{KV}},\\ \\alpha<1$$","pros":["KV 显存下降后 batch size 提升，解码吞吐近似线性增长","冷热分层让长上下文场景不必为最坏情况预留 HBM"],"cons":["换出/换入引入 PCIe 延迟，SLO 敏感场景下抖动明显","KV 量化误差在长上下文注意力中放大，需要逐层校准"],"papers":["paper-efficient-memory-management-for-larg-2023","paper-saem-stage-aware-expert-management-f-2026"],"successors":["alg-disagg-expert-parallel"],"facts":["解决的问题是 MoE 模型层数多、注意力头多，长上下文下 KV cache 显存超过专家权重，成为 batch size 与并发数的硬约束，PagedAttention 的分页只解决碎片不解决容量。","机制步骤：prefill 阶段按页写入 KV 并标记每页热度；解码时按注意力分数识别冷页并异步换出到 host 内存；换入时按需预取并与当前层计算重叠；对保留页做 INT8/FP8 KV 量化、缩放因子随页存储；注意力计算读取压缩 KV、反量化后进入 FlashAttention 流水。","核心公式为压缩 KV 的注意力 $$\\mathrm{Attn}(q,K,V)=\\mathrm{softmax}\\!\\left(\\frac{q\\hat{K}^{\\top}}{\\sqrt{d}}\\right)\\hat{V}$$，其中 $\\hat{K},\\hat{V}$ 为反量化后的键值，缩放因子随页存储，$d$ 为头维度。","负载配方：面向长上下文请求，prefill 阶段写入大量 KV 页，解码阶段按注意力分数区分冷热页；SLO 敏感场景关注换出/换入引入的抖动，batch size 随 KV 显存下降而提升。","部署配方：硬件档位为 HBM 加 CPU/NVMe 分层存储，热 token 保留 HBM、冷 token 换出；KV 量化采用 INT8/FP8 并按页存缩放因子；并行拓扑上与 PagedAttention 分页管理配合按需换入。","稳定性技巧是异步换出与按需预取同当前层计算重叠以隐藏 PCIe 延迟，并对 KV 量化逐层校准；失败模式是换出/换入引入 PCIe 延迟使 SLO 敏感场景抖动明显，以及 KV 量化误差在长上下文注意力中放大。","与 PagedAttention 相比，分页只解决显存碎片，它进一步做冷热分层与量化压缩以扩大容量；与统一 KV 量化相比，它按页热度选择性换出，避免为最坏情况预留 HBM。","适用边界是长上下文、高并发的 MoE 解码；规模上限受 PCIe 带宽与 KV 量化误差约束，上下文越长冷页越多、换入延迟越难隐藏，材料未给出具体上下文长度上限。"],"anchors":["paper-efficient-memory-management-for-larg-2023","paper-saem-stage-aware-expert-management-f-2026"],"pitfalls":["冷页换出/换入走 PCIe，延迟抖动在 SLO 敏感场景下直接体现为 TPOT 尖峰。","KV 量化误差在长上下文注意力分数上被放大，未逐层校准会导致远距离 token 注意力失真。","热度判定滞后会把即将被访问的页换出，造成换入风暴并拖慢解码流水。"]},{"id":"alg-chunked-prefill-piggyback","name":"分块预填与解码捎带","year":2023,"direction":"dir-nvfp4-fp8-quant","tier":"recent","problem":"连续批处理中长 prefill 会独占 GPU 数十毫秒，期间所有解码请求被阻塞，TPOT 抖动剧烈，MoE 的 All-to-All 又放大这种阻塞。","idea":"把 prefill 切成固定大小的 chunk，每个 iteration 只处理一个 chunk，与当前 batch 的解码 token 拼成同一批次一起前向，使解码不被长 prefill 饿死。","how":"解决连续批处理中长 prefill 独占 GPU 数十毫秒、期间所有解码请求被阻塞、TPOT 抖动剧烈的问题；MoE 的 All-to-All 通信进一步放大这种阻塞，使解码请求的 token 间隔出现尖峰。 机制按数据流顺序：新请求进入等待队列并按 token 数切分为固定大小 chunk；调度器每步取一个 prefill chunk 与当前解码 batch 合并为同一批次；合并 batch 走 MoE 路由与分组 GEMM；prefill chunk 的 KV 写入分页缓存，解码 token 追加 KV；输出解码 token，chunk 完成后请求转入解码队列。 TPOT 抖动上界由 chunk 大小硬性约束，可写成 $$T_{\\text{iter}} \\approx \\max(T_{\\text{chunk}}, T_{\\text{decode}})$$，其中 $T_{\\text{chunk}}$ 为单 chunk 前向时间、$T_{\\text{decode}}$ 为解码 batch 前向时间；调度器据此反推满足 SLO 的最大 chunk token 数。","flow":["新请求进入等待队列，按 token 数切分为 chunk","调度器每步取一个 prefill chunk 与解码 batch 合并","合并后的 batch 走 MoE 路由与分组 GEMM","prefill chunk 的 KV 写入分页缓存，解码 token 追加 KV","输出解码 token，chunk 完成后请求转入解码队列"],"formula":"$$\\text{TPOT}_{\\text{p99}}\\approx \\max_{\\text{iter}}\\left(T_{\\text{decode}}+T_{\\text{chunk}}\\right),\\quad \\text{chunk\\_size}\\le \\frac{\\text{SLO}_{\\text{TPOT}}-T_{\\text{decode}}}{\\text{每 token 时延}}$$","pros":["解码 TPOT 抖动被 chunk 大小硬性约束，SLO 可计算","prefill 与解码共享同一前向，GPU 利用率高于分离式方案的低负载场景"],"cons":["chunk 太小则 prefill 吞吐下降，首 token 时延 TTFT 变长","MoE 层 prefill chunk 与解码 token 的专家分布不同，分组 GEMM 形状更碎"],"papers":["paper-sarathi-efficient-llm-inference-by-p-2023","paper-deepspeed-fastgen-high-throughput-te-2024"],"successors":["alg-monomoe-fused-kernel"],"facts":["解决连续批处理中长 prefill 独占 GPU 数十毫秒、期间所有解码请求被阻塞、TPOT 抖动剧烈的问题；MoE 的 All-to-All 通信进一步放大这种阻塞，使解码请求的 token 间隔出现尖峰。","机制按数据流顺序：新请求进入等待队列并按 token 数切分为固定大小 chunk；调度器每步取一个 prefill chunk 与当前解码 batch 合并为同一批次；合并 batch 走 MoE 路由与分组 GEMM；prefill chunk 的 KV 写入分页缓存，解码 token 追加 KV；输出解码 token，chunk 完成后请求转入解码队列。","TPOT 抖动上界由 chunk 大小硬性约束，可写成 $$T_{\\text{iter}} \\approx \\max(T_{\\text{chunk}}, T_{\\text{decode}})$$，其中 $T_{\\text{chunk}}$ 为单 chunk 前向时间、$T_{\\text{decode}}$ 为解码 batch 前向时间；调度器据此反推满足 SLO 的最大 chunk token 数。","负载配方：请求形态为长短混合的在线对话，批大小由解码队列长度决定，SLO 以 TPOT 的 p99 上界为主约束；chunk 大小按 SLO 反推，长 prompt 请求的 TTFT 被拉长但可预测。","部署配方：单机多卡 TP 或 EP 拓扑，prefill chunk 与解码 token 共享同一前向；量化沿用权重与激活的既有方案（材料未给出具体位宽）；KV 使用分页缓存按块写入，chunk 边界与页边界对齐以减少碎片。","稳定性技巧：chunk 大小取 SLO 允许的最大值以兼顾吞吐；对 MoE 层将 prefill chunk 与解码 token 的路由结果合并统计，避免分组 GEMM 形状过碎；失败模式是 chunk 过小导致 prefill 吞吐下降、TTFT 显著变长。","与分离式预填/解码部署的差别：本方法在同一 GPU 池内把 prefill 切片后与解码拼批，不需要跨池 KV 传输与 RDMA 带宽；代价是两阶段共享并行策略，无法各自用最优 TP/EP 配置。","适用边界：适合中低负载、单池部署、TPOT SLO 严格但 TTFT 可放宽的场景；规模上限受 chunk 切分粒度与 MoE 分组 GEMM 效率制约，超长上下文时 chunk 数增多、调度开销与 KV 页碎片上升。","论文引用：paper-sarathi-efficient-llm-inference-by-p-2023；paper-deepspeed-fastgen-high-throughput-te-2024。"],"anchors":["数十毫秒"],"pitfalls":["chunk 切得过小时 prefill 吞吐明显下降，TTFT 被拉长到超出首 token SLO，长 prompt 请求排队时间不可控。","MoE 层中 prefill chunk 与解码 token 的专家分布差异大，合并批次后分组 GEMM 形状更碎，tile 利用率下降反而拖慢单步前向。","chunk 边界与 KV 分页边界不对齐时产生页内碎片，长上下文下 KV 缓存有效容量下降，挤压可支持的并发 batch。"]},{"id":"alg-pd-disaggregation-moe","name":"MoE 预填解码分离部署","year":2024,"direction":"dir-kv-cache-compression","tier":"recent","problem":"prefill 是计算密集、decode 是带宽密集，两者混部时资源争抢导致 TTFT 与 TPOT 无法同时满足 SLO，MoE 的专家并行让两种阶段的并行策略冲突。","idea":"把 prefill 与 decode 拆到不同 GPU 池，prefill 池用大 TP 打满算力，decode 池用 EP 承载大 batch，KV 通过 RDMA 从 prefill 池传到 decode 池。","how":"解决 prefill 计算密集、decode 带宽密集两者混部时资源争抢、TTFT 与 TPOT 无法同时满足 SLO 的问题；MoE 的专家并行使两阶段最优并行策略冲突，混部时 router 与专家布局被迫折中。 机制按数据流顺序：请求先进入 prefill 池按 TP 并行计算生成 KV；KV 按层/页打包经 RDMA 写入 decode 池的 KV 存储；decode 池按 EP 布局接收 KV，router 与专家在本地 rank；decode 池连续批处理生成 token 并原地追加 KV；完成后释放 KV 返回客户端。 两池资源配比可按吞吐方程估算 $$\\frac{N_p}{N_d} \\approx \\frac{R_{\\text{prefill}}}{R_{\\text{decode}}}$$，其中 $N_p$、$N_d$ 为两池 GPU 数，$R_{\\text{prefill}}$、$R_{\\text{decode}}$ 为两阶段单位时间请求处理能力；比例失配即出现一侧空闲一侧过载。","flow":["请求先进入 prefill 池，按 TP 并行计算并生成 KV","KV 按层/页打包，经 RDMA 写入 decode 池的 KV 存储","decode 池按 EP 布局接收 KV，router 与专家在本地 rank","decode 池连续批处理生成 token，KV 原地追加","完成后释放 KV，请求返回客户端"],"formula":"$$\\text{Goodput}=\\frac{\\text{满足 SLO 的请求数}}{\\text{总 GPU 秒}},\\quad \\text{约束}:\\ \\text{TTFT}\\le \\text{SLO}_{\\text{TTFT}},\\ \\text{TPOT}\\le \\text{SLO}_{\\text{TPOT}}$$","pros":["两个阶段各自用最优并行策略，TTFT 与 TPOT 可同时达标","decode 池 batch 大且稳定，MoE 专家利用率高"],"cons":["KV 跨池传输占用 RDMA 带宽，长上下文时传输时间不可忽略","两池比例需按流量预测静态配置，突发流量下易出现一侧空闲一侧过载"],"papers":["paper-distserve-disaggregating-prefill-and-2024","paper-splitwise-efficient-generative-llm-i-2023"],"successors":[],"facts":["解决 prefill 计算密集、decode 带宽密集两者混部时资源争抢、TTFT 与 TPOT 无法同时满足 SLO 的问题；MoE 的专家并行使两阶段最优并行策略冲突，混部时 router 与专家布局被迫折中。","机制按数据流顺序：请求先进入 prefill 池按 TP 并行计算生成 KV；KV 按层/页打包经 RDMA 写入 decode 池的 KV 存储；decode 池按 EP 布局接收 KV，router 与专家在本地 rank；decode 池连续批处理生成 token 并原地追加 KV；完成后释放 KV 返回客户端。","两池资源配比可按吞吐方程估算 $$\\frac{N_p}{N_d} \\approx \\frac{R_{\\text{prefill}}}{R_{\\text{decode}}}$$，其中 $N_p$、$N_d$ 为两池 GPU 数，$R_{\\text{prefill}}$、$R_{\\text{decode}}$ 为两阶段单位时间请求处理能力；比例失配即出现一侧空闲一侧过载。","负载配方：请求形态为长上下文在线服务，prefill 池按 TTFT SLO 配置 TP 度，decode 池按 TPOT SLO 配置 EP 度与大 batch；SLO 分别约束首 token 时延与 token 间隔。","部署配方：prefill 池用大 TP 打满算力，decode 池用 EP 承载大 batch 提升专家利用率；KV 经 RDMA 跨池传输，按层/页打包；量化方案两池可独立选择（材料未给出具体位宽）。","稳定性技巧：按流量预测静态配置两池比例并留缓冲；KV 传输与 decode 计算流水重叠；失败模式是突发流量下比例失配，或长上下文时 RDMA 传输时间不可忽略导致 TTFT 超标。","与分块预填捎带的差别：本方法物理分离两阶段，各自用最优并行策略且 decode batch 大而稳定；代价是引入跨池 KV 传输的 RDMA 带宽开销与两池静态配比的管理复杂度。","适用边界：适合高负载、长上下文、TTFT 与 TPOT 双 SLO 严格的集群部署；规模上限受 RDMA 带宽与 KV 传输量制约，上下文越长、层数越多，跨池传输越成为瓶颈。","论文引用：paper-distserve-disaggregating-prefill-and-2024；paper-splitwise-efficient-generative-llm-i-2023。"],"anchors":[],"pitfalls":["两池比例按预测静态配置，突发流量下 prefill 池或 decode 池单侧过载，另一侧 GPU 空闲，整体吞吐与 SLO 同时恶化。","长上下文请求的 KV 跨池 RDMA 传输时间不可忽略，与 decode 计算未充分重叠时 TTFT 被传输主导。","decode 池按 EP 布局接收 KV 时若层/页打包格式与本地专家分片不一致，需额外重排，增加显存拷贝与延迟。"]},{"id":"alg-moe-expert-cache-prefetch","name":"专家缓存与双阶段预取","year":2025,"direction":"dir-disaggregated-pd","tier":"recent","problem":"专家总数远超单卡显存，解码时按 router 结果动态换入专家，PCIe/NVMe 读取延迟直接暴露在关键路径上，造成解码卡顿与 QoS 抖动。","idea":"用历史路由统计预测下一层将激活的专家，在计算当前层时异步预取到 GPU 显存，配合 LRU 专家缓存与双缓冲隐藏换入延迟。","how":"解决专家总数远超单卡显存、解码时按 router 结果动态换入专家、PCIe/NVMe 读取延迟直接暴露在关键路径上、造成解码卡顿与 QoS 抖动的问题。 机制按数据流顺序：记录每层 router 输出的专家命中历史；用滑动窗口预测下一 iteration 的热门专家集合；在当前层 GEMM 执行时异步发起预取 DMA；预取完成的专家进入双缓冲槽，未命中则回退按需加载；GEMM 从缓存槽读取权重，LRU 淘汰冷专家。 命中率与隐藏条件可写为 $$T_{\\text{prefetch}} \\le T_{\\text{GEMM}}$$，其中 $T_{\\text{prefetch}}$ 为专家 DMA 时间、$T_{\\text{GEMM}}$ 为当前层计算时间；只有预取与计算重叠且命中率高时换入延迟才被完全隐藏。","flow":["记录每层 router 输出的专家命中历史","用滑动窗口预测下一 iteration 的热门专家集合","在当前层 GEMM 执行时异步发起预取 DMA","预取完成的专家进入双缓冲槽，未命中则回退到按需加载","GEMM 从缓存槽读取权重，LRU 淘汰冷专家"],"formula":"$$T_{\\text{layer}}=\\max\\left(T_{\\text{GEMM}},\\,T_{\\text{prefetch}}\\right)+\\left(1-h\\right)T_{\\text{miss}},\\quad h=\\frac{\\text{命中专家数}}{\\text{激活专家数}}$$","pros":["预取与计算重叠后，命中率高时换入延迟被完全隐藏","专家缓存让热门专家常驻，减少重复 DMA 带宽消耗"],"cons":["路由预测错误时预取浪费带宽，反而拖慢当前层","缓存槽占用显存，挤压 KV cache 与 batch size 空间"],"papers":["paper-duoserve-moe-dual-phase-expert-prefe-2025","paper-floe-on-the-fly-moe-inference-on-mem-2025"],"successors":[],"facts":["解决专家总数远超单卡显存、解码时按 router 结果动态换入专家、PCIe/NVMe 读取延迟直接暴露在关键路径上、造成解码卡顿与 QoS 抖动的问题。","机制按数据流顺序：记录每层 router 输出的专家命中历史；用滑动窗口预测下一 iteration 的热门专家集合；在当前层 GEMM 执行时异步发起预取 DMA；预取完成的专家进入双缓冲槽，未命中则回退按需加载；GEMM 从缓存槽读取权重，LRU 淘汰冷专家。","命中率与隐藏条件可写为 $$T_{\\text{prefetch}} \\le T_{\\text{GEMM}}$$，其中 $T_{\\text{prefetch}}$ 为专家 DMA 时间、$T_{\\text{GEMM}}$ 为当前层计算时间；只有预取与计算重叠且命中率高时换入延迟才被完全隐藏。","负载配方：请求形态为专家激活分布偏斜的在线解码，批大小受缓存槽占用显存制约；SLO 以 TPOT 抖动上界为主，热门专家常驻以稳定延迟。","部署配方：单机多卡或单卡多专家分片，专家权重存放于 CPU 内存或 NVMe，GPU 显存划分专家缓存槽与 KV cache；量化沿用既有方案（材料未给出具体位宽）；双缓冲槽按层组织。","稳定性技巧：滑动窗口长度与 LRU 容量按路由偏斜度调参；预取失败回退按需加载保证正确性；失败模式是路由预测错误时预取浪费 PCIe/NVMe 带宽反而拖慢当前层，以及缓存槽占用显存挤压 KV cache 与 batch size。","与按需加载的差别：本方法用历史路由统计预测并异步预取，把换入延迟移出关键路径；代价是预测错误时的带宽浪费与缓存槽的显存开销，按需加载则无预测风险但延迟直接暴露。","适用边界：适合专家激活分布偏斜、热门专家集合稳定的 MoE 解码；规模上限受显存中缓存槽容量与 PCIe/NVMe 带宽制约，路由高度分散或请求分布漂移时命中率下降、预取收益消失。","论文引用：paper-duoserve-moe-dual-phase-expert-prefe-2025；paper-floe-on-the-fly-moe-inference-on-mem-2025。"],"anchors":[],"pitfalls":["路由预测错误时预取占用 PCIe/NVMe 带宽，与当前层真正需要的专家加载竞争，反而拖慢关键路径。","专家缓存槽占用显存挤压 KV cache 与 batch size，长上下文高并发时并发容量下降抵消预取收益。","请求分布漂移使滑动窗口统计失效，热门专家集合频繁变化，LRU 命中率下降、双缓冲槽反复换入换出。"]},{"id":"alg-moe-prefetch-dual-phase","name":"双相专家预取与缓存","year":2025,"direction":"dir-moe-routing-capacity","tier":"recent","problem":"MoE 解码阶段专家权重按 token 路由动态加载，冷专家触发 HBM→SM 的按需搬运造成长尾 stall；预填阶段与解码阶段访存模式差异大，单一缓存策略无法同时满足两阶段 QoS。","idea":"把请求生命周期切成预填相与解码相，用上一 token 的路由分布预测下一层专家集合，在计算当前层时异步预取下一层高概率专家到 L2/显存驻留区，并按相切换缓存淘汰策略。","how":"解决的问题：MoE 解码阶段专家权重按 token 路由动态加载，冷专家触发 HBM 到 SM 的按需搬运，造成长尾 stall；同时预填与解码两阶段访存模式差异大，单一缓存策略无法同时满足两阶段 QoS。 机制按数据流顺序：请求进入调度器标记为预填相，按 chunk 切分并统计各层路由直方图；预填结束前用直方图生成解码相专家热度表并写入每层缓存槽位；解码步 $t$ 计算第 $l$ 层时依据热度表与上一 token 路由对第 $l+1$ 层候选专家发起 cp.async 预取。 命中与回退路径：第 $l+1$ 层到达时命中驻留专家则直接分组 GEMM，未命中者回退按需加载并记入惩罚计数；每 $N$ 步按命中率与惩罚计数重排热度表，淘汰低收益槽位；SLO 逼近时冻结预取深度，优先保障已排队 token 的解码步。","flow":["请求进入调度器，标记为预填相；按 chunk 切分并统计各层路由直方图","预填相结束前，用路由直方图生成解码相专家热度表，写入每层专家缓存槽位","解码步 t 计算第 l 层时，依据热度表与上一 token 路由对第 l+1 层候选专家发起 cp.async 预取","第 l+1 层到达时命中驻留专家则直接分组 GEMM，未命中者回退按需加载并记入惩罚计数","每 N 步按命中率与惩罚计数重排热度表，淘汰低收益专家槽位","SLO 逼近时冻结预取深度，优先保障已排队 token 的解码步"],"formula":"$$T_{\\text{step}}=\\sum_{l=1}^{L}\\Big(\\max\\big(T^{\\text{gemm}}_{l},\\ T^{\\text{pref}}_{l+1}\\big)+\\big(1-h_{l}\\big)\\,T^{\\text{miss}}_{l}\\Big),\\quad h_l=\\frac{|E^{\\text{hit}}_l|}{|E^{\\text{route}}_l|}$$","pros":["把专家加载延迟藏进当前层 GEMM 时间，解码 TPOT 长尾显著收敛","预填相统计路由直方图几乎零额外开销，热度表可跨请求复用"],"cons":["预取错误会占用 HBM 带宽与 L2 容量，挤占注意力 KV 读取，低命中率时反而变慢","热度表依赖路由稳定性；分布漂移或长尾请求下命中率骤降，需额外重排开销"],"papers":["paper-duoserve-moe-dual-phase-expert-prefe-2025"],"successors":[],"facts":["解决的问题：MoE 解码阶段专家权重按 token 路由动态加载，冷专家触发 HBM 到 SM 的按需搬运，造成长尾 stall；同时预填与解码两阶段访存模式差异大，单一缓存策略无法同时满足两阶段 QoS。","机制按数据流顺序：请求进入调度器标记为预填相，按 chunk 切分并统计各层路由直方图；预填结束前用直方图生成解码相专家热度表并写入每层缓存槽位；解码步 $t$ 计算第 $l$ 层时依据热度表与上一 token 路由对第 $l+1$ 层候选专家发起 cp.async 预取。","命中与回退路径：第 $l+1$ 层到达时命中驻留专家则直接分组 GEMM，未命中者回退按需加载并记入惩罚计数；每 $N$ 步按命中率与惩罚计数重排热度表，淘汰低收益槽位；SLO 逼近时冻结预取深度，优先保障已排队 token 的解码步。","核心公式：预取收益判据 $$G_e = p_e \\cdot T_{\\text{gemm}} - c_{\\text{prefetch}} - (1-p_e)\\,c_{\\text{miss}}$$，其中 $p_e$ 为热度表给出的专家 $e$ 下一层命中概率，$T_{\\text{gemm}}$ 为当前层 GEMM 可掩盖时间，$c_{\\text{prefetch}}$ 为搬运代价，$c_{\\text{miss}}$ 为未命中回退惩罚。","负载配方：面向解码 TPOT 长尾敏感的在线服务，请求形态为变长对话与批量并发；批大小按显存驻留区容量与 L2 预算设定，SLO 以 TPOT 分位数为约束；预填相按 chunk 切分以控制直方图统计粒度。","部署配方：硬件档位为高带宽 HBM 加速器，并行拓扑沿用专家并行与 All-to-All 分组；量化可用 NVFP4/FP8 权重与激活以压缩驻留区占用；KV cache 按相区分策略，预填相偏吞吐、解码相偏低延迟读取。","稳定性技巧与失败模式：以惩罚计数与命中率周期性重排热度表，SLO 逼近时冻结预取深度；失败模式包括预取错误挤占 HBM 带宽与 L2 容量、压低注意力 KV 读取带宽，以及路由分布漂移导致命中率骤降并引入额外重排开销。","与相邻算法差别及边界：区别于固定缓存策略与纯按需加载，本方法以两相切分和跨请求热度表复用为核心；适用边界是路由分布相对稳定、预填统计可代表解码分布的场景，长尾请求占比高或分布快速漂移时收益收缩，规模上限受 L2 容量与 HBM 带宽预算约束。"],"anchors":["paper-duoserve-moe-dual-phase-expert-prefe-2025"],"pitfalls":["预取错误会占用 HBM 带宽与 L2 容量，挤占注意力 KV 读取，低命中率时整体反而变慢。","热度表依赖路由稳定性，分布漂移或长尾请求下命中率骤降，需额外重排开销。","SLO 逼近时冻结预取深度会牺牲预取收益，若冻结策略不当可能放大已排队 token 的尾延迟。"]},{"id":"alg-moe-skew-adaptive-dispatch","name":"偏斜感知自适应核调度","year":2026,"direction":"dir-expert-parallel-alltoall","tier":"recent","problem":"MoE 解码 batch 内路由高度偏斜，少数热门专家承载大部分 token，固定 tile 尺寸与固定分组 GEMM 配置导致热门专家核利用率高但尾部专家核空转，整体 GPU 利用率被最慢分片拖住。","idea":"运行时按每层路由计数的偏斜度（基尼系数/最大专家占比）在多个候选 kernel 配置间切换：偏斜高时走大 tile 单专家密集 GEMM，偏斜低时走小 tile 分组 GEMM，并用代价模型预估切换点。","how":"解决的问题：MoE 解码 batch 内路由高度偏斜，少数热门专家承载大部分 token，固定 tile 尺寸与固定分组 GEMM 配置使热门专家核利用率高而尾部专家核空转，整体 GPU 利用率被最慢分片拖住。 机制按数据流顺序：每层路由完成后在 GPU 上做计数归约得到专家 token 直方图与偏斜指标；代价模型比较单专家大 tile、分组 GEMM、混合拆分三种候选配置的预估时延；按选择结果把 token 重排进对应 tile 队列，热门专家单独成批、尾部专家合并成组。 执行与反馈：tcgen05 上以 TMA 加载权重与激活，分组 GEMM 用 mbarrier 流水掩盖尾组启动延迟；执行后回写实测时延在线校正代价模型系数；跨层复用偏斜统计以避免每层重复同步。","flow":["每层路由完成后在 GPU 上做计数归约，得到专家 token 直方图与偏斜指标","代价模型比较候选配置的预估时延：单专家大 tile、分组 GEMM、混合拆分","按选择结果把 token 重排进对应 tile 队列，热门专家单独成批、尾部专家合并成组","tcgen05 上以 TMA 加载权重与激活，分组 GEMM 用 mbarrier 流水掩盖尾组启动延迟","执行后回写实测时延，在线校正代价模型系数","跨层复用偏斜统计，避免每层重复同步"],"formula":"$$\\hat{T}(c)=\\frac{1}{\\kappa_c}\\sum_{e}\\left\\lceil\\frac{n_e}{B_c}\\right\\rceil t^{\\text{tile}}_c+\\lambda\\,T^{\\text{launch}}_c,\\quad c^\\star=\\arg\\min_c \\hat{T}(c)$$","pros":["按层自适应选择核形态，热门专家不再被尾部专家拖慢，解码吞吐提升且尾延迟收敛","代价模型在线校正，能跟随不同模型与 batch 组成的路由分布漂移"],"cons":["每层需 GPU 侧计数归约与主机侧决策，引入额外同步点，小 batch 下开销占比高","候选配置需预先调优并维护多套 kernel，工程复杂度与编译产物体积上升"],"papers":["paper-decoding-the-skew-distribution-aware-2026","paper-probe-co-balancing-computation-and-c-2026"],"successors":[],"facts":["解决的问题：MoE 解码 batch 内路由高度偏斜，少数热门专家承载大部分 token，固定 tile 尺寸与固定分组 GEMM 配置使热门专家核利用率高而尾部专家核空转，整体 GPU 利用率被最慢分片拖住。","机制按数据流顺序：每层路由完成后在 GPU 上做计数归约得到专家 token 直方图与偏斜指标；代价模型比较单专家大 tile、分组 GEMM、混合拆分三种候选配置的预估时延；按选择结果把 token 重排进对应 tile 队列，热门专家单独成批、尾部专家合并成组。","执行与反馈：tcgen05 上以 TMA 加载权重与激活，分组 GEMM 用 mbarrier 流水掩盖尾组启动延迟；执行后回写实测时延在线校正代价模型系数；跨层复用偏斜统计以避免每层重复同步。","核心公式：偏斜度与切换判据 $$S_l = \\frac{\\max_e n_{l,e}}{\\sum_e n_{l,e}},\\quad \\hat{T}(c) = \\alpha_c + \\beta_c \\sum_e \\lceil n_{l,e}/t_c \\rceil$$，其中 $n_{l,e}$ 为第 $l$ 层专家 $e$ 的 token 数，$t_c$ 为配置 $c$ 的 tile 尺寸，$\\alpha_c,\\beta_c$ 为在线校正系数。","负载配方：面向解码阶段 batch 组成动态变化的在线服务，请求形态为高并发短输出；批大小增大时偏斜更明显，SLO 以吞吐与尾延迟双约束；每层决策需控制同步开销，小 batch 下需合并决策点。","部署配方：硬件档位为支持 tcgen05 与 TMA 的加速器，并行拓扑配合专家并行与 All-to-All；量化采用 NVFP4/FP8 权重与激活以降低搬运量；KV cache 按解码相低延迟读取配置，避免与权重加载争抢带宽。","稳定性技巧与失败模式：代价模型在线校正以跟随路由分布漂移，跨层复用偏斜统计减少同步；失败模式包括每层 GPU 计数归约与主机决策引入额外同步点、小 batch 下开销占比过高，以及候选 kernel 多套维护带来的编译产物体积与调优负担。","与相邻算法差别及边界：区别于固定 tile 与固定分组 GEMM 配置，本方法按层偏斜度在单专家密集 GEMM 与分组 GEMM 间切换；适用边界为偏斜显著且 batch 组成可观测的解码场景，偏斜接近均匀时切换收益消失，规模上限受候选配置调优成本与同步开销约束。"],"anchors":["paper-decoding-the-skew-distribution-aware-2026","paper-probe-co-balancing-computation-and-c-2026"],"pitfalls":["每层需 GPU 侧计数归约与主机侧决策，引入额外同步点，小 batch 下开销占比高。","候选配置需预先调优并维护多套 kernel，工程复杂度与编译产物体积上升。","代价模型系数失配或路由分布快速漂移时，切换点判断错误会导致核利用率回退甚至尾延迟放大。"]}];})();
